INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0102623cd3f691b1ef7f', 'plenary_transcript', 'Plenary', '3. Business Statement and Announcement', 'Trefnydd, I''d like to ask for a statement from the Cabinet Minister for Local Government, Housing and Planning. Community right to buy is an important step towards ensuring that local communities across Wales have the agency and the ability to invest in their own futures and to design them. Assets that are owned by communities and that are managed by them can inspire enterprise, create opportunities and help to transform lives. But significant barriers continue in terms of ensuring that local voices are heard and that community interests are safeguarded through legislation. It''s possible that we will hear something from the First Minister soon when he will outline the Government''s legislative programme. But, given the importance of community right to buy to communities across Wales, could the Trefnydd arrange a statement by the Cabinet Minister for Local Government, Housing and Planning, to note the Welsh Government''s detailed plans for a community right to buy Bill, and when we can expect it to be introduced before the Senedd?', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Lis McLean', '', '12149', '', '', 'Plenary', '3. Business Statement and Announcement', '16085', 'http://www.senedd.tv/en/16085?startPos=7612&l=en', NULL, 121.0, 'High', 'digest', 'social_housing; fiscal_and_legislative_context; named_welsh_legislation', 'Context; Housing system', 'Housing minister; First Minister / Cabinet', '', 'Community Right to Buy Bill; community right to buy; legislative programme; right to buy', 0, '2026-08-04T14:03:08.883353', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767734', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('010b647a9d0f6e8534cb', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you, Deputy Presiding Officer, and I will be under a minute.

 When we discussed the current budget during the last Senedd, there was widespread support from Plaid Cymru, including you, Minister, that local government has substantial pressures. We overcame the ludicrous idea of a former finance Minister that the consumer price index indicated local government inflation, as if the change in price of items such as hummus, alcohol-free beer, pet grooming, motor homes, dashboard cameras, sheets of wrapping paper and bottled premium lager affected the cost of running local government services.

 It is my understanding that the areas of local government expenditure on additional learning needs, social services, including elderly care and childcare, homelessness and prevention services are causing pressure on council budgets. Minister, is that your understanding, or do you wish to change that list?', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Mike Hedges', '', '332', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4259&l=en', NULL, 88.0, 'High', 'digest', 'homelessness', 'Housing system', 'Housing minister; Opposition housing leads', '', 'homelessness', 0, '2026-08-04T14:03:05.099538', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768137', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0222e53fdad41a348862', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '5. What action is the Welsh Government taking to meet its social housing targets? OQ64420', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Laura Anne Jones', '', '4562', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', '', NULL, 77.0, 'Medium', 'digest', 'housing_supply; social_housing', 'Housing system; Planning & place', 'Housing minister', '', 'housing targets; social housing', 0, '2026-08-04T14:03:05.229570', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768212', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('02d065f777c950bcda70', 'legislation', 'Senedd Act', 'Local Government Finance (Wales) Act 2024', 'Local Government Finance (Wales) Act 2024
Current stage: Royal Assent (16 September 2024)
Stage history: Bill introduced 20 Nov 2023; Stage 1 16 Apr 2024; Stage 2 16 Apr 2024; Stage 3 09 Jul 2024; Stage 4 16 Jul 2024; Royal Assent 16 Sep 2024', 'https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=42241', '2024-09-16', '', '', '', '', '', 'Senedd', '', '', '', NULL, 84.5, 'Medium', 'digest', 'named_welsh_legislation', 'Context', '', 'Bill progress', 'Local Government Finance (Wales) Act; Royal Assent; Stage 1; Stage 2; Stage 3; Stage 4', 0, '2026-08-04T14:04:28.978062', 'https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=42241', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('041e5e303f728ae71cb6', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you, Minister. I believe you met with the Welsh Cladiators recently, so thank you for that. I''m sure that legislation does take time, but people are living in unsafe buildings, so I urge you to put pressure on those in the coming weeks. So, thank you for your answer to that.

 I''d like to turn to housing. I note your statement on Monday confirmed your commitment, or reconfirmed your commitment, to create 20,000 social homes. Another statement, though, without an annual target means there is no way to measure your Government''s performance. But, of course, housing is a question of supply and demand. There is a severe lack of accountability and transparency on who is actually living in our council and social housing. Data in England shows that significant amounts of housing are being allocated to people who are foreign nationals. So, Minister, will you commit your department to collect accurate nationality data from councils and housing associations so the people of Wales can know who will be living in these houses that taxpayers are subsidising?', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Francesca O''Brien', '', '12190', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=3947&l=en', NULL, 104.5, 'High', 'digest', 'housing_supply; social_housing', 'Housing system; Planning & place', 'Housing minister; Opposition housing leads', '', 'housing associations; social homes; social housing', 0, '2026-08-04T14:03:05.063049', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768138', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('06a94cbc8ee7b0d2c23e', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'It is critical that this place recognises the importance of this industry to Wales and hears the concerns that are coming directly from the industry. So, can I thank Paul Marr and Paul Davies? The both of you have explained clearly today the impact of the policies that we''re talking about here and the impact of those policies on the tourism industry in your constituencies. We must never forget, Members, that, when this place passes down legislation, introduces new taxes or burdens industry with more red tape, there are real people at the other end.

 Can I thank Louise Emery? Her knowledge, experience and years of promoting this industry, not just with words but with direct action, has been remarkable. We both share the view that the tourism sector is a key pillar to the economy in Wales, but Louise has gone further and she has shone a light on how this place, this Government, can work proactively with the industry. As we''ve heard, this industry can be key to us tackling issues such as youth unemployment. Particularly with all of the talk of those not in education, employment or training, you would be hard pressed to find an industry more experienced in providing youth employment opportunities than the tourism sector.

 Louise has shown also how on these benches in Reform we recognise the importance of sustainable tourism. We recognise that this, like any other industry, can have an impact on the area that they operate in. However, to address this we need targeted local action, working with local stakeholders. We don''t need nationwide regulations or more taxation—an approach that amounts to taking a sledgehammer to the issue.

 I''d also like to thank my colleague John Clark for highlighting what the industry itself is telling us. They have still not seen a return to pre-pandemic visitor numbers and the challenge that this industry has in attracting visitors here against our international competitors in Europe is stark. With all that in mind, we must accept that surely our best way forward is to work with the industry to break down cost barriers, so businesses can better compete with international markets. A visitor levy won''t do that. As already highlighted, most overnight stays are already subject to VAT, and, in comparison to our European rivals, we are already taxing overnight visitors at a much higher rate. Applying a visitor levy on top of VAT will simply be implementing a tax on top of a tax. Additionally, this approach will hit working and low-income families hardest. It''ll have little impact on the high-end tourism across Wales, but will dramatically hammer more affordable holiday options and smaller businesses. Governments of the past have had the approach of trying to tax or regulate this industry into growth. That will never work.

 I''d also thank Steven Rodaway as well. You''re absolutely right. The industry has spoken. The 182-day rule is too restrictive and it is damaging the industry and the people that work within this sector.

 And I want to turn to the amendment that the Government has put before us. In the amendment, it says that they will keep the 182-day rule under review. Members, we''ve heard today about the pressures the industry is under and we understand the importance of this industry to every corner of Wales. Saying that you''re going to keep it ''under review'' is not good enough. The industry is struggling. It needs our support, not a Government holding response. Also, what I will mention is it has been brought up today that the 182-day rule would help address the housing crisis in Wales. It hasn''t. We still have a housing crisis. We have a housing crisis because we''ve had decades of a Welsh Government failing to build enough homes. Please don''t try and scapegoat that to the tourism industry. If you want to address the housing crisis in Wales, get on and build more homes.

 Then the amendment says that the visitor levy is about giving local councils a choice in introducing the levy to help fund improvements to the tourism sector locally. This is a false narrative, Members. As someone who has spent the last four years in local government, I know first-hand the pressures that councils are facing. Any moneys from this levy will not go to tourism investment. If you put this power in local councils'' hands to levy additional taxation on local businesses, they will use it to ease their financial pressures, mostly in education and social care, not pressures caused by the tourism industry. Additionally, as the Government should well know, there are already provisions in the local government funding formula to support councils to deal with tourism-related pressures. Councils with high numbers of tourists already receive an uplift in funding. So, if you''re concerned about councils managing tourism-related pressures, you want councils to invest in the tourism sector locally, or want to protect council services, then fund councils properly. Do not scapegoat this again to the tourism sector for Cardiff Bay funding failures.

 Members, we have heard that the sector is a vital component of our economy in Wales, and we''ve heard how this slate of legislation is burdening it. We have the opportunity to tell the industry that we stand with them. Members, reject the amendment and support our motion.', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Tom Montgomery', '', '12183', '', '', 'Plenary', '7. Reform UK Debate: The tourism sector', '16084', 'http://www.senedd.tv/en/16084?startPos=15002&l=en', NULL, 55.0, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'Sector bodies', '', 'visitor levy', 0, '2026-08-04T14:03:17.086362', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#767100', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('06acf59f50c1cfa27886', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'If you offer £120 million this year, I can guarantee Labour will vote for it.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Mike Hedges', '', '332', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=26174&l=en', NULL, 44.0, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'Opposition housing leads', '', 'supplementary budget', 0, '2026-08-04T14:03:10.825793', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767995', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('09791420ae1a87b5c1a5', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'It is a very important point. We absolutely recognise the changing face of the threats that we face currently and the arguments in favour of strengthening defence spending, including in the cyber sector, in which we have real expertise here in Wales, but Wales should not be peculiarly disadvantaged by the way the UK Government has gone about with its decisions on defence spending. Departments in the UK Government in Whitehall would have been able to make the case for protecting budgets. The handing down in this way without negotiation with Wales of ongoing cuts to capital, which were under severe strain anyway, will inevitably mean needing to cut back on spending on health and education. The first supplementary budget allocates £40 million of additional capital funding this year to support the urgent maintenance and repair works across schools, the kind of which the Members mentions. That is put under threat. But, of course, we need to get the supplementary budget through first in order to make that spending.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=1845&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:08.362169', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767495', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('09a78b99d63bc12bd6eb', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'Llywydd, next year, that international profile takes on a new dimension. Wales steps on to one of the biggest sporting stages on earth as we welcome hundreds of thousands of Tour de France fans, and there''s a certain justice in it—for decades we''ve been apologising to cyclists for our gradients, and now the greatest race on earth is coming precisely because of them. It turns out we were sitting on a world-class asset all along.

 But a great event that leaves nothing behind is just a party. Our ambition is a legacy, so I''m proud to announce today a £4.5 million investment over 2026 and 2027 in tourism-related cycling infrastructure. The peloton will pass through Wales in a matter of hours. What it leaves behind must last for decades. This is about converting a moment of global attention into a permanent national asset—routes, facilities and businesses that serve visitors and communities long after the last rider has crossed the line.

 And if we''re inviting the world in, the welcome must be real for everyone. A quarter of all visitors to Wales are disabled; if Wales says ''croeso'' to the world, that word cannot come with small print. It must hold true for disabled visitors, neurodivergent visitors and people with hidden conditions and barriers. That''s why I''m launching Croeso i Bawb, £2 million in grant funding to help tourism and hospitality businesses open their doors wider still. Accessibility is good business, but, more than that, it is simply what ''hospitality'' means.

 Let me turn now to the two questions at the heart of this debate. Firstly, the visitor levy. Where tourism happens, there are impacts on the local area. That''s not a criticism of the sector, it''s a facet of success. Visitor levies are neither unusual nor untested. They operate successfully in destinations across Europe and the world, providing resources for the very infrastructure and services that make places worth visiting in the first place. It''s, rightly, for each local authority to consult and decide, but, where a levy is introduced, it''s an opportunity to make the visitor economy work both for the sector and for the communities that host it, and this Government supports that model.

 Second, the 182-day letting threshold. Tourism matters to our economy; so do homes for local people. Those two truths must be held in balance. And where the balance is wrong, we will act. That''s why our manifesto committed to reviewing the threshold and creating clear, reasonable exemptions where self-catering accommodation would not qualify as a private home. The Cabinet Minister for Finance is considering these matters as an early priority and will set out our proposals in due course.

 Llywydd, the First Minister has said that he is committed to learning at all times, and that will be my approach too. I meet the chairs of the regional tourism forums later this month, and over the summer I''ll continue taking evidence directly from sector representatives across Wales, but I do want to go further. Over the course of this term, we are committed to examining whether the form and function of Visit Wales is right for the sector it serves. I believe the moment has come for a proper stocktake, a reset moment between Government and the sector, leading to a shared vision and action plan, a new deal for the visitor economy. I want the sector to help shape it, and I want the Senedd to help shape it too—the cross-party group, Members on all sides, including the parties opposite and the party behind me—for the whole of Wales, built by the whole of Wales. And in that spirit, let me turn now to the contributions Members have made this afternoon.

 Anna Nicholl shared some of her constituents'' experiences, and I think that, in listening and learning, we need to hold those experiences right at the heart of everything that we do. Steven Rodaway asked us to look at the evidence base, and we certainly will be committed in this and in everything we do to ground everything in the evidence base. We urge Members that want to bring data to our attention to do so, and we will do so ourselves in a transparent manner. I welcome the positive contribution from Shavanah Taj. The levy used well, in partnership with the sector, as we know from across Europe and the world, can actually be an engine of growth and development for the sector. And I know that''s the kind of approach that''s been taken by the sector in Cardiff. There could be lessons elsewhere in Wales.

 I am out of time at this point. The flesh was willing, but the spirit was weak. [ Laughter .] All I would say in closing is: look, every nation tells the world a story about itself, and tourism is how the world comes to hear ours. Let''s make sure that story is worthy of the country and the country worthy of the welcome.', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Adam Price', '', '5030', '', '', 'Plenary', '7. Reform UK Debate: The tourism sector', '16084', 'http://www.senedd.tv/en/16084?startPos=14600&l=en', NULL, 99.0, 'High', 'digest', 'taxation_of_property; second_homes_and_short_term_lets', 'Planning & place; Tax & finance', 'First Minister / Cabinet', '', 'self-catering; visitor levy', 0, '2026-08-04T14:03:17.039270', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#767116', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('09ab718bd5dfde76e8cb', 'plenary_transcript', 'Plenary', '3. Business Statement and Announcement', 'Trefnydd, the Bassaleg residents of Forge Mews have been abandoned from the life we all know for close to five years. The old Bassaleg bridge was deemed to be unfit to be unfit for use, leaving the residents with no direct access to their properties other than on foot. Newport City Council have attempted to resolve the matter, but due to funding needs denied by the former Welsh Labour Government in the last Senedd, they are still locked out of normal life, with a resolution still to be found. Imagine, Minister, five years of having to walk home instead of arriving on your own doorstep, five years of having to factor in extra travel time for work or school runs, five years of having to rely on emergency access for fire, ambulance and police support delaying response times, and five years of seeing your house price fall in value, locking you into negative equity. Those residents don''t have to imagine; it''s their lived reality. To add insult to injury, the council has not even offered them a reduction in their council tax across the last five years, despite a clear lack of services for them. Will the Cabinet Minister for Local Government, Housing and Planning agree to meet with me and the resident body to find a lasting solution to their plight?', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Art Wright', '', '12157', '', '', 'Plenary', '3. Business Statement and Announcement', '16085', 'http://www.senedd.tv/en/16085?startPos=7493&l=en', NULL, 93.5, 'High', 'digest', 'taxation_of_property', 'Tax & finance', 'Housing minister; First Minister / Cabinet', '', 'council tax', 0, '2026-08-04T14:03:08.874044', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767728', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0bd6b170deb2a323eeca', 'oral_question', 'Oral Question', 'Oral Question - OQ64370', 'What assessment has the Cabinet Minister made of the impact of housing and planning policy on the ...', 'https://record.senedd.wales/OralQuestion/64370', '2026-07-08', 'Nigel Williams', '', '5113', '', 'Fflint Wrecsam', 'Senedd (tabled business)', 'Tabled on 08/07/2026', '', '', NULL, 25.0, 'Low', 'dashboard', 'planning_system', 'Planning & place', '', '', 'planning policy', 0, '2026-08-04T14:03:42.314829', 'record_search:type=oral_question:query=housing', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0be2c27c34b8bc212d3c', 'oral_question', 'Oral Question', 'Oral Question - OQ64198', 'What will the Welsh Government do to improve the oversight of housing associations and registered social landlords?', 'https://record.senedd.wales/OralQuestion/64198', '2026-06-18', 'Tom Montgomery', '', '12183', '', 'Clwyd', 'Senedd (tabled business)', 'Tabled on 18/06/2026', '', '', NULL, 15.0, 'Noise', 'archive', 'social_housing', 'Housing system', '', '', 'housing associations; registered social landlords', 0, '2026-08-04T14:03:42.313597', 'record_search:type=oral_question:query=housing', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0cfae2d43639f3283694', 'research', 'Senedd Research', 'Representing Wales: the Welsh Government at EU meetings', 'Representing Wales: the Welsh Government at EU meetings

Published 16/07/2026 | Reading Time minutes

As Brexit approached, over 30 new forums were set up for the UK and the EU to take decisions on their relationship, including on matters which are devolved to and/or affect Wales. The forums were set up under two treaties:

Focusing on the 23 intergovernmental forums set up under the TCA, this article presents updated analysis of Welsh Government attendance at these meetings, where important decisions that affect Wales are taken. It finds that there has been a strong pattern of Welsh Government attendance across meetings, with a few notable exceptions.

Explainers on these arrangements and their history can be found in a series of drop-down menus at the end of this article.

Attendance by Welsh Government is recorded in meeting minutes . Figure 1 uses a colour code to denote attendance (green), non-attendance (red), or where attendance is not specified (yellow). As attendance is at the UK Government’s discretion, it may be that the Welsh Government was not invited to attend a particular meeting. Information on whether or not a devolved government was invited is not published.

Since January 2021, there have been 113 meetings. The Welsh Government was at 80 of these (70.8%) but didn’t attend 22 (19.5%). For the remaining 11 meetings, their attendance was not confirmed.

Figure 1: Welsh Government attendance at meetings held under the UK-EU Trade and Cooperation Agreement (2021-2026)

Source: Meetings of the EU-UK Partnership Council and Specialised Committees under the Trade and Cooperation Agreement (European Commission)

While there is a strong pattern of Welsh Government attendance at meetings, there are notable exceptions for meetings on air transport, law enforcement and judicial cooperation, VAT and intellectual property.

Academic research by Royles, Rowe and Minto concluded that, while devolved government involvement in TCA meetings has improved over time, participation from Scotland and Northern Ireland has been greater than that from Wales. This they attribute to “their more enhanced devolved competences”, pointing to greater attendance at the meetings listed above on air transport, law enforcement and judicial cooperation, VAT and intellectual property. Their research formed the basis of evidence submitted to Sixth Senedd committees in 2024.

Although the Welsh Government can act in an international capacity , it cannot enter into legally binding commitments. Only the UK Government can do this for the UK, and does so on behalf of the four nations.

The Welsh Government’s role in this process is important because UK-EU agreements either effect Wales or fall in devolved competence. The Welsh Ministers and the Senedd are responsible for putting these arrangements in place under the Government of Wales Act 2006.

The parts of the TCA that fall in devolved areas include fisheries, health security, the economy, the environment and some aspects of trade. Reserved matters, like trade or law enforcement and judicial cooperation, also have a significant impact on cross-border cooperation.

29 new joint forums oversee the TCA which are shown in Figure 2. The main forum is the Partnership Council, which is supported by committees and working groups. The participation of civil society is also provided for, as well as parliamentary cooperation between the UK and European parliaments.', 'https://research.senedd.wales/research-articles/representing-wales-the-welsh-government-at-eu-meetings/', NULL, '', '', '', '', '', 'Senedd Research', '', '', '', NULL, 15.0, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'cooperation agreement', 0, '2026-08-04T14:04:48.050537', 'https://research.senedd.wales/research-articles/', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0d0a85c11cd34d149c21', 'plenary_transcript', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', 'Now, as Members will have noticed, we have some technical issues at the moment. We''ll need to suspend proceedings for around 10 minutes to resolve those technical issues. We will provide an update as soon as possible, and we will ring the bell five minutes before we reconvene. So, we''ll suspend proceedings now, please.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', '16085', 'http://www.senedd.tv/en/16085?startPos=22043&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'Legislative Consent Motion', 0, '2026-08-04T14:03:10.437009', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767948', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0d8a9b472dcca647fd77', 'oral_question', 'Question not reached in Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '<p>Progressive housing policies, alongside an effective planning system and local leadership ensure a community-led approach. This will deliver affordable homes that meet the needs of people and communities. We will deliver a new approach to strategic planning that brings housing, regeneration, connectivity and economic development together within a single, coherent vision for Wales.</p>', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', '', 'Cabinet Minister for Local Government, Housing and Planning', '', '', '', 'Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', '', NULL, 55.0, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'planning system', 0, '2026-08-04T14:03:06.989897', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=QNR', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('12119a04648ef33a772c', 'plenary_transcript', 'Plenary', '6. Statement by the Deputy Minister for Public and Preventative Health: Priorities for Public and Preventative Health', 'I''d like to welcome the Minister to her post. I''ll stop the pleasantries here because people are watching the clock and we''ll be here all night. So, anyway, I''ll move on to your statement, Minister.

 It says here that you''ve had bilaterals with Cabinet Ministers and Deputy Ministers across Government. That''s lovely, but I''d like to know what the next steps of those are going to be, really, because if we don''t know what''s coming out of it, they''re just lovely meetings to have, aren''t they? You said here as well that you''ve talked to the First Minister and that Government decision making will be informed by a shared focus on public health. Well, I think we can all agree with that, but what does that look like in practice? We''ve heard these things before, and it would be quite good if we could get some understanding today as to what actually that looks like.

 You did say that officials and ministerial and cross-governance and arrangements are all being established. Fantastic, but what does this mean? How much is this going to cost the Welsh civil service, in terms of having all these cross-ministerial portfolios? Is this more civil servants to do this? Is this going to be managed within the current health portfolio? You also mentioned, further down in your statement, about creating a new budget line within the Government''s overall budget-setting process. Is there a risk with that, even though I''m not against it in principle, that we could end up with a bit of silo working here? That, actually, other departments are all chipping in, trying to look for this pot of money, while, actually, if it sat directly within the departments, it would be easier to spend. If the cross-governmental work was focused on prevention, you maybe wouldn''t need a budget line there. I''m sure the Finance Committee would be quite pleased if it wasn''t there, as it''s something else to look at.

 You also talked about weight-loss medication. This is something I''ve been quite involved in, actually. I haven''t taken it personally. But I think one thing we have to be careful with, with weight-loss medication, is that, yes, it is changing lives, but it''s not changing lifestyles. It cannot be seen as a silver bullet to losing weight long term, because we do know about the longer term health impacts, with osteoporosis in women, with people with cardiovascular problems emerging from these jabs, so I''d just like to know—. There needs to be a way for people to get off the treadmill, as such, of taking these jabs. So, I''d like to know what work you''re doing with primary care to understand how you can work with local gyms, leisure facilities, so that when people are accessing weight-loss medication, their lifestyle is changing along with their life, because if you don''t, it''s just a vicious circle: you''ll come off it, you''ll put weight back on again, and you''re back on the jabs and then end up in A&E with longer term problems, and that''s no way to help our health service.

 You did talk about working quite closely with the wider portfolio across health. I''d be interested to know how much money you''re intending to move into the prevention agenda. I know the Cabinet Minister for sport is here as well, and the Government talked an awful lot during the election period about moving money into that portfolio. So, it would be quite good today to get some figures on how much of that prevention agenda is going to be delivered there and what proportion of that is the budget. I think that''s really important.

 You also mentioned working with the Cabinet Minister for Rural Resilience and Sustainability. I think it''s very important. We talk about healthy food; I''m a big advocate of that. I know there were Members in the Conservative Party who brought forward a food Bill, which was supported across the Chamber, which is really important. But I think we need to make sure we''ve got good-quality food in schools. We''ve all seen the scandal with Thai chicken in our schools. That''s not the sort of food we want to be putting into our kids. So, the prevention agenda is moving money into the schools'' budget, so you can make sure that they can afford those good things in schools, and not imported food from across the world.

 What else here? Lung screening. You talked about a lung screening programme. Well, we had the pilot in the previous Senedd. That was a good success story that came out of it. I''m pleased you''re rolling that out further and going to develop that. The one thing that was raised at the time was chronic obstructive pulmonary disease screening. If we don''t embed COPD screening as part of that lung cancer screening process, you''re literally having another test for something else. So, sometimes, it''s cheaper to do it all at the same time. Yes, you might be double-diagnosing somebody, but if someone''s got lung cancer, you can almost, at the same time, say they''ve got COPD, or they''re developing it, or they have COPD and do not have cancer. So, to get it done first time is the right approach, rather than having numerous different tests for people. Treat it once and get it done with.

 Then you also talked about substance misuse. I know the Deputy Minister for mental health is also sat to your side. To deal with substance abuse—I think we have to look as well—you have to treat the individual, not the offence, as such. And if you are going to move to try and address this problem, mental health support has to be there. I know when Lynne Neagle, for example, was the Minister for mental health, she actually laboured on this quite a lot: that if you do not put the mental health support in place to support people on their substance misuse journey, whether that''s drugs or alcohol, you''re just going to have the revolving door of people getting clean and then coming back in again, because you''ve not dealt with the trauma that''s led people there in the first place.

 And in the interests of time, Deputy Presiding Officer, I think I''ve taken my five minutes, even though I said I was going to be quite brief. So, if you could answer some of those questions, Deputy Minister, I''d be very much obliged. Diolch.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'James Evans', '', '8585', '', '', 'Plenary', '6. Statement by the Deputy Minister for Public and Preventative Health: Priorities for Public and Preventative Health', '16085', 'http://www.senedd.tv/en/16085?startPos=14906&l=en', NULL, 66.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Finance Committee', 0, '2026-08-04T14:03:09.670975', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767836', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('12fd2f573587eed9230f', 'consultation', 'Senedd — Committee work', 'Forward work programme – Finance Committee', 'Forward work programme – Finance Committee

Forward work programme – Finance Committee Forward work programme – Finance Committee Issue Details Issue History Related Meetings The forward work programme of the Finance Committee sets out the work which the Committee is intending to carry out in the following weeks and months. Any documents published indicate the current intentions of the Committee at the time of publishing, however the programme may change at any time to respond to external events. Business type: Other First published: 15/06/2026 Topics Helpful Links Find a Member of the Senedd chevron_right Sign up to updates from Senedd committees chevron_right Senedd Now chevron_right Glossary chevron_right Related No results were found', 'https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=47639', '2026-08-04', '', '', '', '', '', 'Finance Committee', '', '', '', NULL, 42.0, 'Low', 'digest', 'committee_scrutiny', 'Housing system', '', '', 'Finance Committee', 0, '2026-08-04T14:02:48.834389', 'https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=47639', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('134d0797e63b48517399', 'legislation', 'Acts of Senedd Cymru', 'Development of Tourism and Regulation of Visitor Accommodation (Wales) Act 2026', 'Development of Tourism and Regulation of Visitor Accommodation (Wales) Act 2026', 'https://www.legislation.gov.uk/asc/2026/10/2026-04-28/data.xml', '2026-07-31', '', '', '', '', '', 'legislation.gov.uk', '', '', '', NULL, 84.5, 'Medium', 'digest', 'second_homes_and_short_term_lets; named_welsh_legislation', 'Context; Planning & place', '', '', 'Development of Tourism; Development of Tourism and Regulation of Visitor Accommodation (Wales) Act; Regulation of Visitor Accommodation; visitor accommodation', 0, '2026-08-04T14:04:14.608080', 'https://www.legislation.gov.uk/asc/data.feed', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('144fa80ce1d9992eae6e', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'As has already been said, the tourism sector is of huge importance to the communities I represent in Ceredigion Penfro, so I''m pleased to speak up on behalf of the tourism businesses and providers in my constituency who are operating under significant financial pressures.

 Today''s motion refers specifically to the visitor levy or the tourism tax and the 182-day occupancy threshold. I''ve made my views very clear on both of these policies. In fact, one of my very first actions in this Senedd was to appeal to the Cabinet Minister for Enterprise, Connectivity and Energy to reduce the 182-day threshold. And whilst we''ve heard some commitments from the Cabinet Minister for Finance about introducing exemptions, I do not believe that this goes far enough. I believe that there needs to be a fundamental rethink of this policy so that it''s fairer for all providers, not just some.

 I know the Cabinet Minister recognises the importance of tourism to supporting communities and strengthening local economies, and he''s made it clear in correspondence to me that he wants to ensure his engagement with the tourism industry is constructive, evidence led and focused on supporting businesses to thrive. There''s plenty of evidence to show that reducing the 182-day threshold will help the tourism sector and will help support businesses to thrive. Data from the Valuation Office Agency has shown that the number of self-catering businesses is down by 30.7 per cent, and yet in England, over the same period, the fall is only 12.2 per cent. In my view, the difference is because of the 182-day threshold. We''ve all heard compelling evidence why the threshold is unrealistic, how the market is changing, and why a one-size-fits-all approach just doesn''t work. So I hope the Welsh Government will now reflect on the evidence that is already out there showing how damaging this policy really is.

 And it''s not just hurting Welsh business, it''s hurting our people and our communities too. Ninety-four per cent of Welsh members of the Professional Association of Self-Caterers have said they are more stressed because of this specific policy. Many holiday let owners in my constituency are also farmers, who are already competing with so much red tape and regulation and have been pushed into diversifying over the years only to face even more red tape and regulation. I''ve also heard from countless owners about how their family has let their property for 20, 30, even 40 years, sometimes longer, and they are heartbroken that they''re having to consider selling it now. These are people with deep connections to the communities where their properties are.

 I''ve always believed that increasing taxes and regulations on one group of people does not make housing more affordable for another group of people. If we begin to see more tourism businesses close as a result of policies such as the 182-day threshold, there is no guarantee that those properties will become more accessible to local residents. Indeed, there''s a real risk that they could instead be purchased by wealthier buyers from outside the area. And it also impacts our local communities. It could result in fewer visitors, which means reduced footfall and reduced spending in pubs, shops and local attractions, putting many tourism-related jobs at risk. And so, for those reasons, I hope the Welsh Government will be sincere in its commitment to reviewing the policy. The evidence is already mounting and action is needed now. 

 The same holiday owners who are struggling with the 182-day threshold are also facing business rate rises, tax changes and, from next April, a visitor levy could be introduced too. This levy does not support business owners and it does not maintain affordability for visitors. It''s also highly likely to be applied inconsistently across local authority areas, pitting one county against another and risks worsening an already fragile tourism market. And this will not just only tax tourists, it will apply to everyone who stays overnight in Wales, including people within Wales. Llywydd, the tourism sector has been overwhelmed with additional financial pressures, and rather than pause and consider the cumulative impact of all of these policies, the previous Government added more burdens on business owners, and so the new Welsh Government has an opportunity here to reset the balance.

 It also has an opportunity to take a more strategic approach to how the sector is valued and how its long-term sustainability can be secured. For example, how do we properly recognise the contribution made by seasonal workers within our communities, or by those who rely on multiple part-time jobs in the tourism and hospitality industries? These are important questions that require thoughtful consideration if we are serious about supporting a thriving tourism sector, while delivering sustainable economic growth in our communities across Wales.

 So, Llywydd, I look forward to hearing from the Cabinet Minister about his views on these issues and how we can create conditions for the sector to grow and flourish in the future. I can confirm that the Welsh Conservatives will be supporting this motion.', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Paul Davies', '', '145', '', '', 'Plenary', '7. Reform UK Debate: The tourism sector', '16084', 'http://www.senedd.tv/en/16084?startPos=13321&l=en', NULL, 126.5, 'High', 'digest', 'taxation_of_property; second_homes_and_short_term_lets', 'Planning & place; Tax & finance', 'First Minister / Cabinet', 'Decision or commitment', 'I can confirm; holiday let; self-catering; tourism tax; visitor levy', 0, '2026-08-04T14:03:16.903747', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#767097', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('14d8d297488369cd3320', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I welcome many of the steps taken by the Plaid Cymru Government since coming into power in order to address the real challenges facing the health service in Bangor Conwy Môn. We have seen a direct commitment to Betsi Cadwaladr University Health Board as well as additional funding for the health service in the supplementary budget. I''m sure that everyone would recognise the difference that that funding could make for patients and staff, and therefore how important it is that we pass the supplementary budget this afternoon. In looking to the future and to ensure that the good work can continue, we must encourage more efficient use of public funds within the health service. With that in mind, will the First Minister provide an update on the Government''s commitment to establish a health finance efficiency team and when he hopes to see that being established?', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elfed Williams', '', '12165', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=2924&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:08.446582', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767550', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1642b7eaee1da74cece4', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'I will raise my voice, Llywydd.

 Let''s be clear on the implications for additional spending on NHS waiting lists. We support these proposals. They are, after all, the continuation of the successful policy that the last Welsh Government adopted. You do not need a supplementary budget in place to spend in this area. You can carry on the investment now and regularise that spend later in the year. Fearmongering that this money is at risk simply does not bear informed scrutiny.

 And as to the suggestion that if the supplementary budget failed, there would be no money given to ALN at a later date, if that''s accurate then it''s pernicious, it''s vindictive and it''s going to lead to widespread industrial action. The supplementary budget before us has £0.25 billion of unallocated financial resources. I''ve outlined before, the Chair of the Finance Committee has repeated it: that''s not normal. You could use £100 million, as we''ve requested for ALN, and still have a substantial cushion to manage in-year spending pressures.

 Llywydd, we genuinely tried to warn the Government that they were headed for the rocks. My advice now is just as genuine: withdraw the supplementary budget today, negotiate with the teaching unions to resolve this dispute you''ve blundered into, and then bring back a supplementary budget that actually starts to meet the asks of pupils and teachers. When you do, we''ll be here waiting, ready to vote for it. Diolch yn fawr.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Thomas', '', '12156', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=24201&l=en', NULL, 49.5, 'Low', 'dashboard', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', '', 'Finance Committee; supplementary budget', 0, '2026-08-04T14:03:10.612649', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767897', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('16c263fca60cb087d583', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I thank the Member for drawing attention to the genuine pressure that exists, which is caused by childcare costs. Even though my children are getting older now, I remember clearly the heavy costs involved in providing childcare, and we as a Government are determined to help, with regard to the financial costs, the opportunities given to children, and the economic opportunities that follow for parents and so forth.

 The Deputy First Minister will provide an update to the Senedd today on the process of rolling out the childcare offer, as well as information on the cost modelling. The additional investment through the supplementary budget is going to allow us to expand thousands of additional funded childcare places, focusing immediately on expanding childcare for two-year-olds. This is always something that happens in phases: the 12.5 hours, the 20 hours, and then onwards to the youngest children. That''s how it''s planned, to increase the financial envelope and the workforce at the same time. But we''re clear that this transformational change requires a childcare sector that is strong and sustainable, a skilled workforce, and a budget that works for providers as well as parents.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=3302&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:08.481769', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767536', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('18dfedb967556e59bdb0', 'calendar', 'Senedd forward look', 'Equality, Human Rights and Social Justice Committee — 23 September 2026, 09.30', 'Equality, Human Rights and Social Justice Committee is scheduled to meet on 23 September 2026 at 09.30.
Meeting status: Confirmed
This is an opportunity to influence: committee papers and any call for written evidence are normally published in the two weeks beforehand.', 'https://business.senedd.wales/ieListDocuments.aspx?CId=983&MId=16247', '2026-09-23', '', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '', '16247', '', '2026-09-23', 48.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Equality, Human Rights and Social Justice Committee; written evidence', 0, '2026-08-04T14:04:40.435421', 'https://business.senedd.wales/mgWebService.asmx#GetAllMeetingsByDate', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('19766bdf9ec6310cd40b', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: Legislation', 'Today I''ll talk about our first phase of legislation. This recognises the dual importance of bringing early momentum to this legislature''s work whilst allowing space to build agreement and develop genuinely impactful legislation across a full four-year term. There are several areas where action can be taken swiftly.

 Firstly, we want to protect and enhance Wales''s unique sense of community. Our nation is a rich tapestry of urban and rural, north and south, young and old, but the legacy of a decade and more of austerity has chipped away at our sense of place. We will therefore proceed with the development of a community right-to-buy scheme and provide the legislative basis to enable eligible community groups to nominate and register valuable community assets to be given the right of first refusal when the owners decide to sell. We want more, not fewer, places that allow people to meet, learn, organise and make decisions together, and we want these to remain in the hands of our communities.

 Secondly, the value my Government places on fairness has motivated us to take action to strengthen the rights of tenants in the private rented sector. We will initially bring forward legislation focusing on strengthening our enforcement framework and the regulatory role of Rent Smart Wales, as well as requiring the sharing of rent data. This will lay the groundwork for more substantial changes that will improve housing affordability, make rents fairer, and limit no-fault evictions, to be brought forward later in this Senedd term. We''re also developing proposals to legislate for the right to adequate housing, because nobody should be forced to suffer the anxiety and unacceptable stigma that so often comes with having nowhere to call home.

 Thirdly, to leave a greener legacy for generations to come, we will bring forward environmental proposals that support the developing climate and nature action plan. We will make existing legislation clearer, more workable and better able to support delivery on climate change, nature recovery, woodland protection, waste management improvements, environmental enforcement and the sustainable use of natural resources.

 We also intend to develop a statutory duty on rural-proofing, to ensure rural needs are considered consistently when policies are developed and delivered. I made a promise to lead a Government for the whole of Wales and this long-overdue change honours that. Consultation will begin imminently on these environmental and rural resilience proposals. As a package, they will strengthen legal and policy tools, support fair and effective regulation, and help deliver cleaner places, healthier ecosystems and stronger rural communities.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '4. Statement by the First Minister: Legislation', '16085', 'http://www.senedd.tv/en/16085?startPos=8319&l=en', NULL, 313.5, 'Critical', 'immediate', 'private_rented_sector; rent_controls_and_affordability; evictions_and_possession; rent_smart_wales; homelessness; social_housing', 'Housing system; Private rented sector', 'First Minister / Cabinet', 'Consultation open', 'Rent Smart Wales; adequate housing; community assets; consultation; evictions; housing affordability; no-fault evictions; private rented; private rented sector; rent data; right to adequate housing', 0, '2026-08-04T14:03:08.939665', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767726', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('19d0ed706b7c8b42b29f', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Thank you, Llywydd. As noted, this is the first time that I have spoken in a Plenary debate in my capacity as Chair of the Early Years, Children, Young People and Education Committee. The committee discussed the supplementary budget as it relates to its remit at its first meeting on 8 July. The committee agreed to write to the Minister for finance, and that letter was published on Monday.

 During our discussions regarding our programme of work, it became clear that additional learning needs are a key priority for the committee. The committee noted its disappointment that none of the money allocated as part of the supplementary budget was allocated for ALN, as was the case at the time. Members of the committee noted that schools and local authorities are facing significant funding pressures in terms of ALN, and there is a need to address those pressures. The committee also asked for a timetable for the sustainable longer term funding plan for ALN.

 The committee would like more clarity regarding other key areas, such as free school meals, childcare and children''s health. Regarding free school meals, we are seeking clarity regarding the assumptions that underpin pupil numbers and the unit rate associated with the expansion of the free school meals programme as well, please.

 Regarding childcare, the committee would like clearer data on the progress being made in terms of delivering the current 12.5 hours of childcare under the Flying Start programme for all two-year-olds throughout Wales, so that we can see what is left to deliver and how much this will cost.

 The committee is also eager to scrutinise the impact of health expenditure on children and young people specifically. As part of this, we need assurance that children will benefit from the additional funding for the NHS allocated in the supplementary budget. The committee was relatively supportive of the allocation in terms of health, but it would like to understand the impact of the investments on children specifically. In addition, we would like some clarity regarding the expected impact on paediatric services and waiting times as a result of the investment. Thank you.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Sera Evans', '', '330', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=25391&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:10.746126', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767964', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1c96552b0075982398d9', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'As with other healthcare systems, including in other parts of the UK, the health service here faces significant financial challenges. I think that is clear to everyone. We need more work certainly, and actions, to put it on a sustainable footing. Working on the efficiency element is very, very important. The supplementary budget, of course, which we have before us today, includes £100 million of additional funding to support a reduction in waiting times, £45 million of capital funding for the health service, and the Betsi Cadwaladr University Health Board will benefit directly from that funding stream.

 The Cabinet Secretary for Health and Care, as well as officials, are reviewing the current arrangements in terms of efficiency, with the intention of strengthening them and noting a clear set of actions by the end of the first 100 days, which will be in about 43 days now. But beyond the idea of efficiency in general, I think we need a long-term approach that includes turning increasingly towards the preventative agenda, and our attitude to that is also part of our first 100 days commitment.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=2986&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:08.451864', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767556', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1cd3f40a6b871e385dc1', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'I''m extremely disappointed with that question. Certainly, I don''t know whether those statistics are accurate or not. But I am disappointed that you are insisting on pursuing this time and time again in this Chamber. As I said, the housing crisis has been created because of a shortage of social housing to meet demand. Everyone in Wales deserves a roof over their head and a safe place to live. So, I don''t want to pursue this issue any further.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4217&l=en', NULL, 66.0, 'Medium', 'digest', 'social_housing', 'Housing system', 'Sector bodies; Housing minister', '', 'social housing', 0, '2026-08-04T14:03:05.095311', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768133', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1e9ae385c9fbc79a27ec', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much. I do agree with you that we do need to accelerate the planning process, particularly in the area of housing. It''s not acceptable that it takes years sometimes for developments to bear fruit. So, it is my intention to announce during the first 100 days that we will be making a call for evidence for reform of the planning system in the area of housing specifically, so that we can try to get professional people—people like you who have been council leaders and who understand the planning barriers at the grass roots—to bring evidence forward so that we can proceed to reform ''Planning Policy Wales'', and to make it more fit for purpose and more swift in response to the needs of our communities.

 There were two Acts that were passed at the end of the last Senedd that bring planning policies together, and I do think that that in itself is going to help issues, but it doesn''t go halfway far enough.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=5185&l=en', NULL, 104.5, 'High', 'digest', 'planning_system', 'Planning & place', 'Housing minister', 'Consultation open', 'Planning Policy Wales; call for evidence; planning policy; planning system', 0, '2026-08-04T14:03:05.191564', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768193', NULL, NULL, NULL, NULL);
