INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c48213f7e3aaf578f3e', 'research', 'Senedd Research', 'Air Quality and Public Health', 'Air Quality and Public Health

Published 22/07/2026 | Reading Time minutes

Air quality is an important public health issue in Wales. This research briefing examines the main sources of air pollution, how air quality is monitored and regulated, the health effects of pollution, and how pollution levels have changed over time.

Air pollution can be caused by both human activity and natural processes. Major pollutants such as particulate matter, nitrogen oxides, and ozone, are continuously monitored across Wales. The main human sources of air pollution include transport, domestic burning, industry, electricity production, and agriculture.

The burden of poor air quality is equivalent to around 1,000 to 1,400 deaths each year in Wales. A large body of evidence shows that air pollution can cause negative health outcomes, including respiratory and cardiovascular diseases, cancer, adverse pregnancy outcomes, and effects on cognitive health. Exposure and risk are not evenly distributed, with some groups and communities more affected than others. Wider social and economic consequences include pressures on the NHS and the interaction between pollution and existing inequalities.

Action at both the UK and Wales level has sought to limit the production of air pollution and people’s exposure to that pollution. Notable legislative milestones include the Environment Act 1995 and the Environment (Air Quality and Soundscapes) (Wales) Act 2024 (the 2024 Act). Legislation empowers and obliges the Welsh Government and local authorities to act to reduce air pollution, including by declaring Air Quality Management Areas and smoke control areas , and introducing policies to bring pollution below legal thresholds. In 2026, the last Welsh Government used powers in the 2024 Act to set targets for reducing fine particulate matter pollution . The Welsh Government has also acted to reduce pollution from domestic burning, agriculture, and transport .

Concentrations of many major pollutants, including sulphur dioxide, nitrogen dioxide, and particulate matter, have fallen substantially in recent decades . Continuing challenges include urban ozone pollution and local variation in exposure. It can be challenging to isolate the specific impact of individual policy measures. Case studies focussing on Port Talbot steelworks closure and 50 mph speed limits on trunk roads illustrate how local air quality can change in response to industrial and transport developments. Action to reduce greenhouse gas emissions can also have a co-benefit of reducing air pollution, and therefore improving human and environmental health.

Research briefing by Charlotte Morgan and Dr Matthew Sutton , Senedd Research, Welsh Parliament

Senedd Research acknowledges the parliamentary fellowship provided to Charlotte Morgan by the Engineering and Physical Sciences Research Council (EPSRC) which enabled this briefing to be completed.', 'https://research.senedd.wales/research-articles/air-quality-and-public-health/', NULL, '', '', '', '', '', 'Senedd Research', '', '', '', NULL, 20.0, 'Noise', 'archive', 'local_government_enforcement', 'Housing system', '', '', 'environmental health', 0, '2026-08-04T14:04:46.483932', 'https://research.senedd.wales/research-articles/', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c9b434855a4f7fc63f8', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'I want to start by celebrating the huge contribution that tourism makes to Wales and my constituency in Ceredigion Penfro. Ceredigion Penfro is one of the most beautiful places in the world, shown by the millions who visit each year. In Ceredigion Penfro, you can travel from sandy beach to rolling hill to ancient woodland—and sometimes find all three in one place. From the only coastal national park in the UK in Pembrokeshire, to the remote wilderness of Ceredigion''s Cambrian mountains. From Tenby to Trefdraeth and from Aberaeron to Arberth, it''s no wonder that people across Wales and around the world want to visit Ceredigion Penfro.

 Tourism accounts for around 13 per cent of all employment in Ceredigion and 23 per cent in Pembrokeshire, so I''m delighted that this Government recognises the importance of the tourism industry to Wales. But evidence gathered from the previous Government showed that high levels of tourism, if not managed, can have a negative impact on an area. High levels of second homes and short-term lets can impact on local housing markets and the sustainability of local communities, particularly in areas where properties are not occupied for much of the year.

 It''s important that we are promoting tourism that provides maximum benefit to our people, environment, language and culture, and I welcome the lots of ideas that have come up in this debate already. So, I fully support the Government taking steps to enable sustainable tourism that secures jobs and income into local economies and which benefits our communities, environment, language and culture. And I support measures that prevent harm. That''s why I support the visitor levy as a choice for local authorities to ensure that local communities reap the rewards of tourism. Funds raised through the visitor levy enable investment in the local environment, the Welsh language and culture, and local infrastructure, which also supports tourism.

 However, it''s also important for the Government to act quickly when good policy intentions are not delivering the intended change and, in the case of the 182-day threshold, may be in danger of taking us in the wrong direction. Since becoming a Member of the Senedd, I''ve met with many constituents who have told me about the challenges that the 182-day rule for holiday lets is creating. I''ve heard about the pressure that the policy is putting on many self-catering businesses and the toll it is taking on people running local businesses. I''ve heard how it is threatening the viability of some local businesses, as well as jobs and spend in the wider economy, and I''ve also seen examples where it''s not achieving the intended outcome for the local housing market.

 So, whilst I fully support the intention of the 182-day rule, I also welcome this Plaid Cymru Government''s commitment to keep the 182-day occupancy threshold under review, and I urge the Government to begin this work quickly, so that we can find pragmatic solutions that better support the original purpose of the policy. This should include whether 182 days is the right threshold, but also have clear and reasonable exemptions, particularly where a property would not qualify as a private home. We need clear guidance to avoid holiday let owners being left stunned by unaffordable backdated council bills, sometimes by three or four years, or living with the mental stress that they soon could be. So, that''s why I''m pleased to support the Government amendment today, and I urge other Members to do so. Diolch.', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Anna Nicholl', '', '12178', '', '', 'Plenary', '7. Reform UK Debate: The tourism sector', '16084', 'http://www.senedd.tv/en/16084?startPos=12193&l=en', NULL, 77.0, 'Medium', 'digest', 'taxation_of_property; second_homes_and_short_term_lets', 'Planning & place; Tax & finance', '', '', '182 days; holiday let; holiday lets; second homes; self-catering; short-term lets; visitor levy', 0, '2026-08-04T14:03:16.759645', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#767061', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6e56d102baa15cf59325', 'consultation', 'Senedd — committee consultation', 'Welsh Government Draft Budget 2027-28', 'Welsh Government Draft Budget 2027-28

This is an open Senedd consultation. Responding puts NRLA''s position formally on the record.

Welsh Government Draft Budget 2027-28, start date: Fri, 31 Jul 2026 00:00:00 GMT, end date: Fri, 25 Sep 2026 23:59:00 GMT

Welsh Government Draft Budget 2027-28 Welsh Government Draft Budget 2027-28 View the background to this consultation View all current consultations Purpose of the consultation The Senedd’s Finance Committee is seeking information to inform its scrutiny of the Welsh Government’s 2027-28 Draft Budget proposals. We are interested in exploring expectations of the 2027-28 Budget, including financial readiness for the financial year ahead. The Finance Committee looks at the Welsh Government’s Draft Budget from a strategic, overarching perspective. Where relevant and possible, we are also keen to work with other Senedd committees to ensure that proposals for specific departments or ministerial portfolios are considered in detail. The Committee asks for views on the specific questions included in the consultation letter (PDF, 192KB) and any general views in relation to the Draft Budget. To submit your views, please complete the online form . Providing Written Evidence Interested parties are invited to submit written evidence by completing a consultation form or by writing to the Clerk of the Finance Committee by Friday, 25 September 2026 . We are keen to hear from as many people and organisations as possible. If you would like to submit your views but do not want / are not able to complete the online form, please write to the Committee ( SeneddFinance@senedd.wales ) and the Committee’s clerks can arrange with you a different way for your voice to be heard. The Committee’s postal address and telephone number can be found at the end of the consultation page. The Senedd has two official languages, Welsh and English. In line with the Senedd’s Official Languages Scheme , the Committee welcomes contributions in both or either of our official languages, and we ask organisations that are subject to Welsh Language standards or schemes to respond in line with their own obligations. Please inform the Committee when submitting responses if you intend to provide a translation at a later date. Please see guidance for those providing evidence for committees . Disclosure of information Please ensure that you have considered the Senedd’s policy on disclosure of information before submitting information to the Committee. Overview of the analytical methodology All responses received through this consultation will be analysed using a mixed methods approach. We will analyse text with the support of Natural Language Processing (NLP) software. The purpose of this approach is to enable u

Closing date: 25 September 2026.', 'https://business.senedd.wales/mgConsultationDisplay.aspx?ID=632', '2026-07-31', '', '', '', '', '', 'Senedd committee', '', '', '', '2026-09-25', 245.0, 'Critical', 'immediate', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'NRLA named', 'Consultation open; Opportunity to influence', 'Finance Committee; closing date; consultation; consultations; draft budget; written evidence', 1, '2026-08-04T14:02:44.304875', 'https://business.senedd.wales/mgRss.aspx?f=76', NULL, NULL, NULL, NULL);
