INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7a96e1eb50cc7275de0a', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'It might well have been a priority for the last Government. I doubt whether it''s a priority for your party right now because you voted against the supplementary budget, which offered £145 million to develop diagnostic hubs and elective care hubs across Wales. But, yes, it is a priority.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Mabon ap Gwynfor', '', '269', '', '', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', '16086', 'http://www.senedd.tv/en/16086?startPos=1651&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:04.845058', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768058', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7b7669849680b34b263a', 'plenary_transcript', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', 'The Cynnal payment has the potential to make a real difference to families facing the sharpest end of child poverty, particularly in communities like Afan Ogwr Rhondda, where levels of deprivation are among the highest in Wales and household budgets are already under enormous pressure. But, for it to work, families need clarity and confidence that this support will reach them directly. We know there are clear precedents for additional payments being disregarded within the benefits system, including the Scottish child payment and local welfare provision. But the Welsh NHS and social care bonus show that without Department for Work and Pensions protection, the value of a Government payment can be reduced through the universal credit system as it''s then classed as earnings. If the DWP is unwilling to provide that protection for an anti-poverty payment aimed at children, does the Dirprwy Brif Weinidog agree that this underlines exactly why decisions affecting poverty in Cymru should be made in Cymru by a Government that understands and prioritises communities in Cymru? And will she set out what discussions the Government is having to ensure that the Cynnal payment is simple to access and protected in full?', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Elyn Stephens', '', '12164', '', '', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', '16084', 'http://www.senedd.tv/en/16084?startPos=710&l=en', NULL, 77.0, 'Medium', 'digest', 'welfare_and_support', 'Housing system', 'First Minister / Cabinet; LGHP Committee members', '', 'universal credit', 0, '2026-08-04T14:03:15.519129', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#766807', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7c7ddc97e563a84df84e', 'oral_question', 'Question not reached in Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', 'What assessment has the Cabinet Minister made of the impact of housing and planning policy on the ability of local authorities to deliver enough affordable homes for local people in Flintshire and Wrexham?', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Nigel Williams', '', '5113', '', '', 'Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', '', NULL, 55.0, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'planning policy', 0, '2026-08-04T14:03:06.987962', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=QNR', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7c9544cf12a411e4b1be', 'legislation', 'Acts of Senedd Cymru', 'Planning (Consequential Provisions) (Wales) Act 2026', 'Planning (Consequential Provisions) (Wales) Act 2026', 'https://www.legislation.gov.uk/asc/2026/7/2026-04-28/data.xml', '2026-07-23', '', '', '', '', '', 'legislation.gov.uk', '', '', '', NULL, 39.0, 'Low', 'dashboard', 'named_welsh_legislation', 'Context', '', '', 'Planning (Consequential Provisions) (Wales) Act', 0, '2026-08-04T14:04:14.610067', 'https://www.legislation.gov.uk/asc/data.feed', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7cb5aab632b9d3b74fb9', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Mike, your comments are noted. So, that agreement—[ Interruption .]', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Darren Millar', '', '171', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=24358&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:10.629926', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767896', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7cbc1e982314e6ceec9b', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you for that answer; it was longer than I expected. We have agreed there is an increasing demand for certain council services. There are also environmental health and trading standards—vital services that need to be supported. Things like food safety and trading standards protect consumers. Minister, how much extra money have you and fellow Ministers asked for from the finance Minister to meet this increased demand out of the £247 million unallocated?', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Mike Hedges', '', '332', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4371&l=en', NULL, 82.5, 'Medium', 'digest', 'local_government_enforcement', 'Housing system', 'Housing minister; Opposition housing leads', '', 'environmental health', 0, '2026-08-04T14:03:05.110956', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768149', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7d7e337b884f42042e5c', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much. Unfortunately, I can''t comment on specific developments in specific constituencies. Welsh Ministers are responsible for making decisions in those areas, and who knows with this particular issue, so I can''t talk about that specifically. But you do bring forward an important point about how our planning policies and our strategies look at issues relating to data centres, which bring us back to the point made by James Evans, namely the need to look again at the main national development framework, ''Future Wales''. We do need to reform that. This is one example of why, and so that work is happening. During our first 100 days, there will be a specific announcement about the process that needs to happen with that. There is a specific process; we can''t just sit down and change it. We have to go through a process, and we will be making an announcement about that during the first 100 days.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=5065&l=en', NULL, 71.5, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister; Other committee chairs', '', 'Future Wales', 0, '2026-08-04T14:03:05.180802', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768175', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7f7d8a182a006c05d1af', 'consultation', 'Senedd — Committee work', 'Legislative Consent: Steel Industry (Nationalisation) Bill', 'Legislative Consent: Steel Industry (Nationalisation) Bill

Legislative Consent: Steel Industry (Nationalisation) Bill Legislative Consent: Steel Industry (Nationalisation) Bill Issue Details Issue History Related Meetings The Steel Industry (Nationalisation) Bill (the Bill) was introduced in the House of Commons on 14 May 2026. The long title to the Bill notes that it is “A Bill to make provision enabling the Secretary of State in certain circumstances to make regulations relating to the transfer of securities issued by, or property, rights and liabilities of, a steel undertaking; and for connected purposes.” The Bill is subject to the legislative consent process under Standing Order 29 . This is when the consent of the Welsh Parliament is sought by the UK Government to legislate on an issue in relation to Wales that has regard to devolved matters. The Legislative Consent Motion for the Bill was agreed in Plenary on 14 July 2026. Legislative Consent Memorandum – June 2026 On 23 June 2026, the Business Committee pre-emptively agreed (33KB) that the Legislation Committee and the Economy, Energy and Connectivity Committee should report to the Senedd by the morning of 14 July 2026. The Welsh Government laid a Legislative Consent Memorandum (PDF 248KB) on the Bill before the Senedd on 25 June 2026. The Legislation Committee laid its report (PDF183KB) on 14 July 2026. Business type: Legislative Consent First published: 25/06/2026 Topics Helpful Links Find a Member of the Senedd chevron_right Sign up to updates from Senedd committees chevron_right Senedd Now chevron_right Glossary chevron_right Related No results were found', 'https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=47487', '2026-08-04', '', '', '', '', '', 'Legislation Committee', '', '', '', NULL, 63.0, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', '', 'Legislation Committee; Legislative Consent Motion', 0, '2026-08-04T14:02:51.027445', 'https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=47487', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7f84b8b83d621ef63f45', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Firstly, we acknowledge and appreciate that a supplementary budget like this is not the ideal time to make substantial changes. Also, we''re aware of the tightening fiscal environment and an inherited budget legacy. We have an ongoing shortfall in educational funding; that much is obvious. Whilst the £120 million allocation of additional funding for additional learning needs won''t solve all the challenges it faces, to reject it as part of the supplementary budget would be to play politics with school funding. Unlike others in the Chamber, we won''t be using this as a political football to gain some illusion of control.

 There is strong consensus among many in this Chamber about what we could do and what we can work to deliver for the people of Wales. It is time we genuinely worked together collaboratively and co-operatively to deliver these. Additional healthcare funding and the shift towards primary care is a step in the right direction, as is the £20 million capital funding for social housing. The housing crisis is a health crisis, and we know, as does the Government, that collective solutions will be more cost-effective, helping those who need it most, where they need it most, in their homes. This is something we will expect to see prominently feature in the next budget.

 Likewise, noting the £1 bus fare provision, we want to see investment in public transport go further, with cleaner, integrated, sustainable travel putting money back into people''s pockets as well as addressing the urgent need to transition away from fossil fuels.

 On climate, I''d like now to move to the most glaring omission in this supplementary budget. There is a small, but welcome, uplift in both resource and capital allowances to develop and implement climate change policy, green growth and environmental protection. But this funding is apparently ring-fenced for the Welsh Government energy service, not to address the climate change mitigation and adaptation. The Met Office yesterday released data showing that more than 2,700 people are thought to have died from heat-related causes during the May and June heatwaves in England and Wales. Of those, almost half died as a result of the extra heat caused by human-induced warming. The authors of this report said:

 ''It''s time we woke up to the fact that we now live in a country with dangerously hot summers. To protect people during future extremes, we must urgently adapt''.

 Our summers are 3-4 degrees Celsius hotter than they would have been without human-induced climate change. Last month, 35.9 degrees Celsius was recorded at Bute Park in Cardiff, breaking the previous June record of 33.7 degrees Celsius, set in 2000. That week, children were sent home from school. As a country, we are incredibly underprepared. The UK Climate Change Committee''s recent climate risk assessment found that critical action was needed in Wales to address health risks from heat. It estimates that UK-wide heat deaths could increase from around 1,400 to between 3,000 and 10,000 in the 2050s without further adaptation. The health toll is rising and it''s costing lives.

 This week, as was mentioned earlier today, North Wales Fire and Rescue Service have been tackling a major incident with the outbreak of wildfires near Conwy mountain. Families are having to flee their homes to safety. This is a frightening situation for all involved, and our thoughts are with anyone impacted by this devastating situation. Having declared a climate emergency all those years ago, where is the action to treat the situation as the genuine crisis that it is?

 For the people of Wales, these issues cannot wait until the next budget, or the next one. The climate change action fund has not changed but the reality of the situation has. Where will the money come from to address this unfolding crisis? The Government must provide assurances that climate mitigation and adaptation will be given the necessary prominence it needs, going forward, and within the next budget.

 Finally, I''d like to say, as a Member of a party that never whips its Members in any Parliament, we will be voting to support this budget. I believe that to do otherwise would be an irresponsible dereliction of duty. Diolch.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Anthony Slaughter', '', '5025', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=25725&l=en', NULL, 77.0, 'Medium', 'digest', 'social_housing; fiscal_and_legislative_context', 'Context; Housing system', 'Sector bodies; Opposition housing leads', '', 'social housing; supplementary budget', 0, '2026-08-04T14:03:10.780409', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767972', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('818ba8dab005681b082b', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'I was delighted to hear yesterday of the Government''s commitment to introduce the community right to buy. There are good examples of market towns that succeed in creating energy and activity, through a number of indigenous businesses rooted there. In my own constituency, there are a number of examples in Machynlleth of community groups buying community assets, such as churches and pubs and so on, and keeping them going for the benefit of the community and the local economy. Can the Cabinet Minister make a statement on community right to buy? Thank you.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Elwyn Vaughan', '', '8371', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=3643&l=en', NULL, 49.5, 'Low', 'dashboard', 'social_housing', 'Housing system', 'Housing minister', '', 'community assets; community right to buy; right to buy', 0, '2026-08-04T14:03:05.029025', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768134', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('81dc56c4479971d750e0', 'calendar', 'Senedd forward look', 'Finance Committee — 24 September 2026, 09.30', 'Finance Committee is scheduled to meet on 24 September 2026 at 09.30.
Meeting status: Confirmed; Hybrid
This is an opportunity to influence: committee papers and any call for written evidence are normally published in the two weeks beforehand.', 'https://business.senedd.wales/ieListDocuments.aspx?CId=984&MId=16250', '2026-09-24', '', '', '', '', '', 'Finance Committee', '', '16250', '', '2026-09-24', 48.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; written evidence', 0, '2026-08-04T14:04:40.447990', 'https://business.senedd.wales/mgWebService.asmx#GetAllMeetingsByDate', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('82069dec4ef52b39c05d', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: Legislation', 'Finally, on the first phase of the legislative programme, I turn to the economy. Whilst far too many major economic levers still reside in Westminster, we will not stop making the case for their transfer. But, as an immediate step, a tax maintenance Bill will continue Wales''s tax devolution journey. These proposals will help the Welsh Revenue Authority continue to administer the land transaction tax and landfill disposals tax effectively by making operational and technical changes to clarify, enhance and futureproof the Welsh tax Acts and to support information sharing between the WRA and local authorities.

 My Government will never place limitations on our level of ambition for Wales. The new national development agency will spearhead our mission to halve Wales''s productivity gap with the rest of the UK in the next decade. With the Minister for enterprise already having announced an expert advisory panel, there is considerable momentum behind this goal. We won''t take a final decision on the form of that agency until we''ve been able to consider the panel''s advice, but we will be ready to bring forward legislation should that be required.

 This practical approach will underpin our activity in a number of areas, including child poverty and the Welsh language. We will review the evidence, we will consider the options available, and we will bring forward legislation where that is what is needed to deliver the outcomes on the ground that we want to see.

 Before concluding, Llywydd, I''ll say a brief word about other legislation. It''s the combination of primary and secondary legislation that makes up the backbone of the developing Welsh statute book. The Government''s vision is not only to bring forward individual instruments that improve the lives of the people of Wales, but at the same time to create a body of Welsh law that is clear, coherent and accessible to those who rely on it. Central to this vision is our continuing programme of consolidation and codification of Welsh legislation.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '4. Statement by the First Minister: Legislation', '16085', 'http://www.senedd.tv/en/16085?startPos=8617&l=en', NULL, 198.0, 'Critical', 'immediate', 'taxation_of_property; fiscal_and_legislative_context; named_welsh_legislation', 'Context; Tax & finance', 'First Minister / Cabinet; Delivery bodies', 'Legislative commitment; Opportunity to influence', 'Land Transaction Tax; advisory panel; land transaction tax; legislative programme; will bring forward legislation', 0, '2026-08-04T14:03:08.967284', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767749', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('821206712827c70e9057', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'The proposal is to agree the motion. Does any Member object? [ Objection. ] I will defer voting under this item until voting time.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=26478&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:10.863209', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767979', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('827ae64fd99e88d4af5a', 'research', 'Senedd Research', '“A generational challenge” – young people and the labour market', '“A generational challenge” – young people and the labour market

Published 13/07/2026 | Last Updated 13/07/2026

The number of young people who are not in education, employment or training (NEET) has been high on the political agenda over recent months. Each number represents a young person’s life and future.

Young people face a range of complex and interconnected barriers to accessing education and entering the workplace. Ahead of Wednesday’s Plenary debate on young people and employment, this article explores these challenges, the support available from governments to address them, and the changes needed to improve outcomes for young people.

There are three main sources of data published on young people who are NEET. The statistical first release (SFR), the annual population survey (APS), and pupil destinations from schools. According to the Welsh Government, the SFR is the “definitive statistical source” for estimates of NEETs; this is published annually. The APS is a rolling year annual estimate; which is published twice a year. Careers Wales carries out an annual survey of school leavers in the October; this data is used to calculate the proportion of young people who are NEET. It’s not advised to draw comparisons between the different data sources.

Annual Population Survey (APS) statistics estimate that the proportion of young people aged 16-24 in Wales who were NEET was 17% in the year ending December 2025; an increase of 5.5 percentage points over the previous year. Note, there is increased uncertainty around estimates from the APS.

The graph below shows the Statistical First Release (SFR) data on the proportion of young people who were NEET and whether they were unemployed (actively looking for work and available to start work) or were economically inactive (not looking for work and not available to start work).

Using the SFR measure, in 2024, the proportion of young people aged 16-24 who were NEET was 13.7%, which is 47,100 young people. Of those who were NEET, 14,300 were unemployed and 32,800 were economically inactive. Over recent years, young people in Wales who are NEET have been considerably more likely to be economically inactive than unemployed.

Source: StatsWales, Estimated 16 to 24 year olds not in education, employment or training in Wales by economic activity and age group

Being NEET, particularly for a long time, can have permanent ‘scarring effects’ on a young person. Recent research from academics at University College London found that, in midlife, someone persistently out of employment, education or training as a young person is:

The challenges young people face in Wales are similar to those across the UK. The interim report to the UK Government on young people and work by Alan Milburn (the Milburn review) highlights young people across the UK who are NEET are becoming detached from the labour market, and are not looking for work.

The big change identified by the Milburn review is the considerable increase over the past decade in the proportion of people who are NEET due to a work-limiting health condition. Over the same period, the percentage of young people in the UK who are NEET has gone from being around the European average to being higher than all EU Member States except Romania.

The Milburn Review also highlights that some groups of young people are particularly likely to be NEET – care leavers, carers, young mothers, and youth offenders. It finds that these groups are failed at transition points by the services which are supposed to support them into the labour market.

Both the UK and Welsh governments provide support for young people who are NEET. The UK Government provides support through job centres, and has also developed a range of initiatives that operate in Wales:

The previous Welsh Government launched the Young Person’s Guarantee (YPG) to provide everyone aged 16 to 24, living in Wales, with support to gain a place in education or training or help to get into work or self-employment. It aims to prevent young people from becoming NEET. The YPG covers a number of support packages including:', 'https://research.senedd.wales/research-articles/a-generational-challenge-young-people-and-the-labour-market/', NULL, '', '', '', '', '', 'Senedd Research', '', '', '', NULL, 15.0, 'Noise', 'archive', 'data_and_evidence', 'Context', '', '', 'StatsWales', 0, '2026-08-04T14:04:50.050173', 'https://research.senedd.wales/research-articles/', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('8288dc0956c3fe989e5f', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Diolch, Lywydd. Thank you for the range of views on this supplementary budget from across the political parties, Members, and also for the questions and contributions from committee Chairs and committee members as well.

 To Reform, thank you for outlining your three red lines. We don''t agree with your first red line, but we are working on your other two red lines. Part of that is in this budget and part of that is in the work that the health Minister is doing. 

 To the Conservatives, I can, as I said, see the logic to part of your reasoning in opposing the previous Government''s budget, as restated in this budget. And just to Darren, I can count; a good state school education made sure of that. 

 I thank the Green Party for your support, unwhipped as it is, and your challenge to us in that contribution to do more on climate change. 

 To Labour—and I''ll start by saying that you''re lucky, Huw, that I''m old enough to pass over a slightly condescending comment on my influence in Government—however, I''m totally flabbergasted by Labour. Today, you have had the opportunity to support a £120 million ALN support package for our schools and councils. [ Interruption .] You could have—[ Interruption .] Did you put your name forward to speak in the debate? Go on, then, you''re the leader of your group.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elin Jones', 'Cabinet Minister for Finance', '162', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=26024&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:10.808752', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#768008', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('82ed77628efd327a6f4f', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Tenure-neutral Retrofitting Programme', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', '', '', '', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', '', NULL, 71.5, 'Medium', 'digest', 'energy_efficiency', 'Property & energy', 'Housing minister', '', 'retrofitting', 0, '2026-08-04T14:03:05.250550', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768195', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('82f117fd3c41641837f4', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you, Minister, for your answer. So, I take that as a ''no'', but, don''t panic, I thought that would be the reason, or the answer. But my team and I have been hard at work collecting this data from councils. We take Cardiff Council as an example; I''m sure our friend in the corner there will be listening with interest to this. The figures I''ve obtained under the Freedom of Information Act 2000 are shocking. I have them right here, and they will be made public as we speak.

 So, let''s look at the council''s social housing stock of over 14,000 homes, where nationality is actually recorded. More than 31 per cent of lead tenants are foreign nationals. On the waiting list of over 9,000 properties, non-British applicants are 22 per cent of those recorded. And of the new tenancies handed out last year, almost 30 per cent of recorded allocations went to non-British applicants. Meanwhile, 35 per cent of those in temporary accommodation are foreign nationals, where the data is actually recorded. This equates to thousands of foreign national households in one city, which is being subsidised.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Francesca O''Brien', '', '12190', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4091&l=en', NULL, 148.5, 'Critical', 'immediate', 'private_rented_sector; homelessness; social_housing', 'Housing system; Private rented sector', 'Housing minister; Opposition housing leads', '', 'social housing; temporary accommodation; tenancies', 0, '2026-08-04T14:03:05.074853', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768155', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('83bc2425895a632fe522', 'research', 'Senedd Research', 'What does the Armed Forces Bill mean for Wales?', 'What does the Armed Forces Bill mean for Wales?

Published 13/07/2026 | Reading Time minutes

In the coming months, Senedd Members will be asked to vote on whether to grant consent for provisions in the UK Government’s Armed Forces Bill .

If passed, the Bill would introduce changes to the Armed Forces Covenant in Wales and establish a new Defence Housing Service with responsibility for improving service accommodation across the UK.

This article sets out why the Senedd is being asked to grant consent, and explores some key measures in the Bill which are relevant for policy-makers in Wales.

The Armed Forces Bill is a UK Government Bill. It was introduced in the House of Commons in January 2026, and is currently making its way through the scrutiny process in Westminster. The House of Commons Library has published a briefing explaining the key measures in the Bill.

The Bill primarily deals with defence issues which are reserved to Westminster , but it includes provisions which relate to devolved matters. Although the UK Parliament can still legislate on devolved matters, the Sewel convention provides that it does not normally do so without the consent of the Senedd.

The UK Government is seeking consent from the Senedd for provisions to expand the Armed Forces Covenant , which would affect the functions of Welsh Ministers and certain devolved public bodies. In its Legislative Consent Memorandum (LCM) for the Bill, the Welsh Government has argued that other aspects of the Bill should also require consent.

The Armed Forces Covenant is a statement of the moral obligation which exists between the nation, the government and the armed forces.

Currently, the law places a duty on certain public bodies to have due regard to the Covenant principles when carrying out particular functions (sometimes known as the Covenant Duty).

The Armed Forces Covenant Duty is a legal obligation which applies to specified bodies. When exercising certain functions, these bodies must have due regard to:

If passed, the Bill would extend the Covenant Duty to national and devolved governments.

Local authorities, education bodies and health bodies in Wales are already subject to this duty . However, the Bill effectively extends the duty by requiring all specified bodies to have regard to the Covenant when exercising any functions relating to an expanded list of 12 key policy areas .

According to the Explanatory Memorandum that accompanies the Bill, the aim of these changes is to ensure the needs of the armed forces community are considered by all relevant policymakers and decision makers.

There has been widespread support for an extension of the Covenant Duty during scrutiny of the Bill.', 'https://research.senedd.wales/research-articles/what-does-the-armed-forces-bill-mean-for-wales/', NULL, '', '', '', '', '', 'Senedd Research', '', '', '', NULL, 50.0, 'Medium', 'digest', 'fiscal_and_legislative_context', 'Context', '', 'Legislative commitment', 'LCM; explanatory memorandum', 0, '2026-08-04T14:04:49.551152', 'https://research.senedd.wales/research-articles/', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('85a79a117878efe577b3', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Local Government, Housing and Planning Committee: Remit of the Committee', 'So, if we move to item 2: Local Government, Housing and Planning Committee—remit of the committee. The purpose of the item is to note the committee''s remit. I''m assuming that everybody has received papers in relation to that. And the remit is outlined paragraph 5 of paper 1. I''ll just quickly go through it. It''s to examine legislation and hold the Welsh Government to account by scrutinising its expenditure, administration and policy matters, encompassing, but not restricted to, local government, communities, housing, planning and regeneration. Does anybody have any comments with regard to that remit or the statement? Okay. All right.', 'https://record.senedd.wales/Committee/16169', '2026-07-09', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. Local Government, Housing and Planning Committee: Remit of the Committee', '16169', 'http://www.senedd.tv/en/16169?startPos=2539&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', '', 'Local Government, Housing and Planning Committee', 0, '2026-08-04T14:03:13.632975', 'https://record.senedd.wales/XMLExport/Download?meetingID=16169&xmlDownloadType=EnglishTranscript#767182', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('87c6b90a31871af5cde0', 'plenary_transcript', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', 'Thank you. Well, you''ve identified there that we need to do this work in a phased manner, and that''s what we''ve been clear about from the outset. You''re right to underline that the commitment that the previous Government made to providing childcare places through the Flying Start scheme for those aged two years for 12.5 hours hasn''t been delivered. That''s what the funding in the supplementary budget is going to enable us to do, namely to complete that step. That''s the first step as we build towards our ambition of providing 20 hours of childcare for every child in Wales from nine months to four years of age. This is the important first step. As this work has already been started, the funding in the budget is going to help us to reach that target of delivering that in full, and then, of course, to extend and build on top of that.', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Sioned Williams', '', '8670', '', '', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', '16084', 'http://www.senedd.tv/en/16084?startPos=86&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:15.446666', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#766796', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('87cb116f6202fa633b2f', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Thank you. James Evans, as Chair of the Climate Change, Environment, Sustainability and Rural Affairs Committee. James Evans.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=25541&l=en', NULL, 60.5, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee; supplementary budget', 0, '2026-08-04T14:03:10.758967', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767968', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('87e14aa429a7d082620e', 'plenary_transcript', 'Plenary', '5. Statement by the Deputy First Minister and Cabinet Minister for Social Justice and Equality: Update on Early Years Childcare and Play', 'Diolch, Lywydd. I''d like to declare an interest, as I have a beautiful 11-month daughter who will be going into childcare next month. But I''d like to thank the Government and the Deputy First Minister for her statement today and all the work that''s clearly being done on this policy. I don''t think we can overstate how transformational this policy is going to be, and I think, when people ask what has Wales done differently and what has devolution achieved, previously, they might have pointed to free prescriptions or the 5p bag charge, and I think, at full roll-out, I really believe it''s going to be this policy. But it needs to be done right—no pressure there.

 One issue that''s being raised with me a lot is general workforce capacity for the expansion, and specifically Welsh-medium provision. I know from my own experience that one nursery I approached in Cardiff was at full capacity until 2027, and there are not many Welsh language providers already. 

 And then I''ve also had providers raise issues specifically with support for younger babies, from nine months until two years, and I was assured in your statement today that that''s going to be in the later part of the roll-out, which will allow for this capacity building up. But I just wonder if you could provide some clarity there. I think investment in the supplementary budget is obviously going to really help this as well. But yes, once this—', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Kiera Marshall', '', '12166', '', '', 'Plenary', '5. Statement by the Deputy First Minister and Cabinet Minister for Social Justice and Equality: Update on Early Years Childcare and Play', '16085', 'http://www.senedd.tv/en/16085?startPos=13514&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:09.512393', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767810', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('88e8d62dcb4ed35da749', 'consultation', 'Senedd — Committee work', 'Forward work programme – Local Government, Housing and Planning Committee', 'Forward work programme – Local Government, Housing and Planning Committee

Forward work programme – Local Government, Housing and Planning Committee Forward work programme – Local Government, Housing and Planning Committee Consultation: Priorities for the Local Government, Housing and Planning Committee Issue Details Issue History Related Meetings The forward work programme of the Local Government, Housing and Planning Committee sets out the work which the Committee is intending to carry out in the following weeks and months. Any documents published indicate the current intentions of the Committee at the time of publishing, however the programme may change at any time to respond to external events. On the 9th July 2026 the Committee held its first meeting . During the meeting Members discussed options for determining a strategic approach to the work within their remit, including how to set out priority areas for scrutiny over the term. To help inform these discussions and to shape the Committee’s forward work programme, Members agreed to launch a consultation on priorities for the Seventh Senedd. Consultation: Priorities for the Local Government, Housing and Planning Committee The Committee is seeking views from people and organisations on the issues they believe it should prioritise in the Seventh Senedd. Further information on how to submit your views is available on the consultation page . Please share this consultation with anyone who you think would be interested in submitting their views. Business type: Other First published: 11/06/2026 Consultations Priorities for the Local Government, Housing and Planning Committee (running until 14/09/2026) Topics Helpful Links Find a Member of the Senedd chevron_right Sign up to updates from Senedd committees chevron_right Senedd Now chevron_right Glossary chevron_right Related No results were found', 'https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=47562', '2026-08-04', '', '', '', '', '', 'Local Government, Housing and Planning Committee', '', '', '', NULL, 98.0, 'High', 'digest', 'committee_scrutiny', 'Housing system', '', 'Consultation open', 'Local Government, Housing and Planning Committee; consultation; consultations; seeking views', 0, '2026-08-04T14:02:52.205212', 'https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=47562', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('89502dd478a386afb2a0', 'plenary_transcript', 'Plenary', '6. Member Debate under Standing Order 11.21(iv): Young people and employment', 'Now, younger generations today may want all of the same things that we wanted back in the days. I mean, I remember my first official paid job when I was 17 or 18 in the Sweater Shop in town. I was paid £2.65 and it really was an awful job. But the first thing that I got to do was to buy my first pair of Nike trainers, because up until then, it was Matchstick all the way, because that was what my parents could afford to buy me from Woolworths. But, of course, young people now want the same things. They want to make their own money. They want to make sure that they can pay their way in life and, of course, start building a future, not only for themselves, but also for many others. Many of them have caring responsibilities. They want to be able to buy a house or even start a family.

 Now, Llywydd, as the former health Secretary Alan Milburn has set out in his review, we risk a lost generation of young people. One in eight between the ages of 16 and 24 are not in employment, education or training, otherwise known as NEETs, and I was shocked, really, to find that the data from the end of last year showed that the situation in Wales is actually even worse. One in six young people are not in work, not in education or training, and that should really wind each and every one of us up and make us angry enough to want to do something about it and to work together on these issues, because youth unemployment is not a fringe issue. It is actually the symptom of a systemic failure, bigger than any one policy, bigger than any department or Government, and clearly, now, it demands an even bigger and better response.

 Now, I saw during my time at TUC Cymru that the last Welsh Government took some really positive steps. The young person''s guarantee that was rolled out, when we were coming out of the COVID pandemic, helped around 10,000 young people to get into work; 30,000 apprenticeships were started; and more people were helped to further their education or even start their own business. But clearly, though, that guarantee hasn''t been universally effective. So, it hasn''t done all the things that we were hoping to do. Only around half of the people that were supported through these various schemes actually went on to achieve a positive outcome. And that''s just the people who were even aware that this support existed in the first place and were able to take advantage of it and to navigate through it as well. But what about the people who weren''t aware, who weren''t able to navigate the systems that were set up?

 Now, as set out by the previous skills and social partnership Minister, Jack Sargent, the various schemes that make up the young person''s guarantee are going to be replaced by a new employability support programme, starting next year. I think that if we do this right, it genuinely can be a golden opportunity for us to do things differently here in Wales, to take what works and to streamline it with a real laser focus on moving young people into good, fair work jobs and other opportunities. The UK Government also operates a number of schemes for young people in Wales. The youth jobs grant, which started last month—that gives a real financial incentive for some employers to hire young people who have been out of work and are claiming universal credit. And, of course, there is the economic inactivity trailblazer scheme, which has been piloted in Blaenau Gwent, Denbighshire and Neath Port Talbot, and is currently being reviewed, as I understand it. This scheme, which looks at the underlying big causes of long-term unemployment, gives people the tailored support that they actually need, whether that''s for mentoring, counselling or any other kind of special support that that person may need.

 Now, despite all of the good work, all of the stuff that we''ve done so far, the issue with youth unemployment is not unique to Wales, but we can lead from the front when it comes to finding those solutions and implementing them. And we have to start, of course, with the evidence. Let''s listen to the people who know best, and that is the young people who are actually at that sharp end, who are facing these real challenges on a day-to-day basis, because we don''t have all of the answers, and that is the truth. Some people, young people in particular, are being let down more than others.

 The latest stats, the official stats from the Welsh Government, show that 40 per cent of people with disabilities between the ages of 19 and 24 are not in education, employment or training. We know it''s not because they lack skills or aspiration or any of those things. It is actually a failure, an abject failure of society, a lack of opportunity and a lack of proper support that''s being given. In reality, one in three disabled workers are not getting the reasonable adjustments that they actually need in the first place. Relatively few public sector organisations even have the highest level of Disability Confident accreditation. And according to Mencap, 86 per cent of young people with learning disabilities want to be in paid work, and in reality, it''s only 5 per cent—5 per cent—who actually are. This is mind-boggling, and that''s just not right.

 So, yes, while we have these schemes and they are transforming some lives, there are clearly gaps in the provision, and we know they exist and we need to do something about them. Now, when young people with disabilities consistently say that the systems that they''re meant to be using, that are meant to be there—. Well, they say, ''They''re not actually built with us in mind.'' And that''s not an opinion, that''s their own individual lived experience. These are the people who know the issues best, and the systems would work better if we did a better job of listening to the people who use them. So, that should always be our starting point—for this Welsh Government, for all of us in this Senedd, we really need to, always, get out into our communities, listen and learn and act.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Shav Taj', '', '12175', '', '', 'Plenary', '6. Member Debate under Standing Order 11.21(iv): Young people and employment', '16086', 'http://www.senedd.tv/en/16086?startPos=8103&l=en', NULL, 22.0, 'Noise', 'archive', 'welfare_and_support', 'Housing system', '', '', 'universal credit', 0, '2026-08-04T14:03:05.445142', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768228', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('89757c3e16b29e88220f', 'written_statement', 'Welsh Government — Written Statement (notification)', 'Written Statement: Outcome of the First Supplementary Budget 2026-2027', 'Written Statement: Outcome of the First Supplementary Budget 2026-2027
Elin Jones MS, Cabinet Minister for Finance.

 Today, the Senedd voted against the Welsh Government''s First Supplementary Budget for 2026-2027. This outcome is deeply disappointing. The Budget would have provided an additional £433 million of investment to support key public services and deliver commitments to the people of Wales. It contained no reductions to existing services and was focused on directing additional funding to areas facing significant pressure.

 Read the statement: https://www.gov.wales/written-statement-outcome-first-supplementary-budget-2026-2027', 'https://www.gov.wales/written-statement-outcome-first-supplementary-budget-2026-2027', '2026-07-14', '', '', '', '', '', 'Welsh Government', '', '', '', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:04:54.653173', 'mailbox:senedd-monitor@nrla.org.uk:FIXTURE-004', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('89b1b53148e053b9b35f', 'consultation', 'Welsh Government — Consultation (notification)', 'Consultation: Implementing the Building Safety (Wales) Act 2026', 'Consultation: Implementing the Building Safety (Wales) Act 2026
We want your views on how we implement the Building Safety (Wales) Act 2026, including the remediation regulations, protections for leaseholders, and how building height and storeys are measured.

 The Act creates an occupation-phase fire and structural safety regime for regulated buildings of at least 11 metres or five storeys, designates local authorities as building safety authorities, and empowers the Residential Property Tribunal to make remediation orders and remediation contribution orders.

 Proposed leaseholder protections include no charge where the landlord is responsible for the defect, caps for landlords with net worth over £2m, no charges on leases valued under £175,000, and full protection from cladding remediation costs.

 This consultation closes on 7 September 2026.

 Read the consultation: https://www.gov.wales/implementing-building-safety-wales-act-2026-html', 'https://www.gov.wales/implementing-building-safety-wales-act-2026-html', '2026-06-15', '', '', '', '', '', 'Welsh Government', '', '', '', '2026-09-07', 203.0, 'Critical', 'immediate', 'private_rented_sector; building_safety_and_leasehold; named_welsh_legislation', 'Context; Private rented sector; Property & energy', '', 'Consultation open', 'Building Safety (Wales) Act; Residential Property Tribunal; building safety; cladding; closes on; consultation; landlord; landlords; leaseholder; leaseholders; remediation contribution; remediation orders; we want your views', 0, '2026-08-04T14:04:54.608044', 'mailbox:senedd-monitor@nrla.org.uk:FIXTURE-001', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('8ae239334c8fb5647936', 'plenary_transcript', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', 'Thanks for your response. Cabinet Minister, households across Wales are facing further cost-of-living pressures as prices keep rising. Also in Plaid''s ''The First 100 Days'' document was a commitment to review Welsh benefits such as the discretionary assistance fund. The Welsh Conservatives have always advocated for struggling families to be able to access the support that they''re entitled to, something that sadly did not happen under Labour. In 2023, the Welsh Government made £90 million available to support people with the cost of living when it came to fuel, yet less than £65 million had been spent. Whilst 427,000 households were eligible for support, only 316,000 households applied. Labour failed to properly inform the people of Wales about the assistance that they could receive, and I sincerely hope that doesn''t happen here under Plaid Cymru''s watch. So, what plans does the Welsh Government have to review the Welsh benefits system and help prevent households from being in crisis in the first place?', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Natasha Asghar', '', '336', '', '', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', '16084', 'http://www.senedd.tv/en/16084?startPos=1729&l=en', NULL, 60.5, 'Medium', 'digest', 'welfare_and_support', 'Housing system', 'Sector bodies; First Minister / Cabinet', '', 'discretionary assistance fund', 0, '2026-08-04T14:03:15.622013', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#766855', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('8c21534fec8497f1fd8c', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much. ''Planning Policy Wales'' is kept under continual review to ensure that it remains effective, relevant and responsive to emerging evidence. Officials are currently reviewing planning guidance, and they are doing so to identify which aspects may need to be updated in future to ensure that the planning framework reflects the priorities of this Welsh Government.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4834&l=en', NULL, 60.5, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'Planning Policy Wales; planning guidance; planning policy', 0, '2026-08-04T14:03:05.159197', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768142', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('8cbbd1910efc7640500e', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'The new legislation that I was involved in drawing up in the last Senedd is more far-reaching than the legislation in England, which came into force some years ago. We are consulting on new regulations. I pushed the previous administration to include the ability to do that. So, we are consulting on new regulations that will mean that those people living in buildings that haven''t been remediated, or who are facing additional costs because their service charges have increased because of work that has to be done—those people will have a route to tribunal, once those new regulations are in place. Now, that is a significant step forward, and it''s going to take a little time, a few months, before we bring those regulations into force. I hope that everyone will support—I''m sure that you will support—those regulations.

 There are three aspects of this in reality, aren''t there? There is the new legislation in Wales, but there is also the remediation work, which is extremely slow in happening; it is extremely slow—we accept that. I have invited the companies that are continuing with this work to meet with me next month, where they will get a very clear message that this Government insists that that remediation work should be accelerated, and that the pace should go up.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=3846&l=en', NULL, 71.5, 'Medium', 'digest', 'building_safety_and_leasehold', 'Property & energy', 'Housing minister', '', 'service charges', 0, '2026-08-04T14:03:05.051321', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768156', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('8f7f000783a544d9e16a', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Well, Llywydd, former US President Lyndon B. Johnson once said that the first rule of politics is to be able to count. It''s a simple rule, but it''s one that the Cabinet Minister for Finance clearly didn''t think about when she was putting her supplementary budget together. We were, of course, expecting Labour to capitulate, but the feud between the two left-wing parties in the Senedd appears to be continuing. But the political reality is this: the arithmetic—[ Interruption .] I''ll happily take an intervention. Give me one second. The political reality is this: the arithmetic in this Senedd means that Welsh Government budgets and Welsh Government legislation cannot be agreed without cross-party agreement. You have to secure a majority of the votes cast. That agreement has not been secured, and it''s bonkers to bring something to the Senedd for a vote without securing it.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Darren Millar', '', '171', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=24288&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:10.620828', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767906', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('90e68b4da57502173bfb', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', 'Thank you, Minister. I''m glad to hear it''s so full. Your published ministerial responsibilities include official statistics, including the census, social research and the national survey for Wales. Effective government depends on understanding how Wales is changing and ensuring that future planning reflects that evidence. What research has your department undertaken into the demographic changes in Wales since the implementation of the nation of sanctuary policy and how are those findings being incorporated into the evidence used to forecast future demand for housing, NHS services, school places, transport infrastructure and other public services across Wales? If those demographic changes are not being factored into Government planning, how can you be confident that your forecasts accurately reflect the future needs of Wales? This is not being divisive or any other adjectives you may wish to throw at our party; the people of Wales deserve to understand how the Government determines the future requirements of our nation, and your portfolio is central to ensuring that those decisions are informed by robust evidence and accurate data. Thank you.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Steven Rodaway', '', '12191', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', '16085', 'http://www.senedd.tv/en/16085?startPos=3705&l=en', NULL, 16.5, 'Noise', 'archive', 'data_and_evidence', 'Context', '', '', 'National Survey for Wales', 0, '2026-08-04T14:03:08.518537', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767584', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('92317fbe6456b5973a39', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Away you go, you''re fine.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=26315&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:10.848197', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#768004', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('928c85a725b67c502a33', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much for the question. The town centre taskforce that we''re going to be announcing more about quite soon will address the structural challenges facing town centres, including looking at business rates and planning reform, and by working collaboratively with partners and maintaining a strong focus on delivery to help town centres adapt, attract investment and activity and thrive in the years ahead.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=3476&l=en', NULL, 99.0, 'High', 'digest', 'taxation_of_property; planning_system', 'Planning & place; Tax & finance', 'Housing minister', '', 'business rates; planning reform', 0, '2026-08-04T14:03:05.016994', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768147', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9365dce8a12576804cab', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Before I go into details on the position of Welsh Labour, I want to thank Elin Jones for her engagement with me on the supplementary budget, and I do hope that she knows of the respect that my colleagues and I have for her. I suspect that if she''d had more freedom to negotiate we wouldn''t be in the situation that we''re in today.

 Unfortunately, I fear that there are others in Plaid Cymru who thought that they didn''t need to negotiate, or they preferred to do that through attacking videos on Facebook and briefings to the media. In looking to the process for next year''s budget, I do hope that the Government will reflect on how to avoid the disorder seen over the last three weeks.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Thomas', '', '12156', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=23959&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:10.579761', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767951', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9581d219d1d2c656c240', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Diolch, Lywydd. The issue of parking at the Maelor hospital in Wrexham is raised with us time and time again, and some residents have told us that they''ve arrived sometimes up to three hours before an appointment just to find a parking space. And that will be contributing to the 27,000 missed appointments at the Maelor last year. We''ve raised that repeatedly with the health board, alongside other local Members as well, the council and residents, too, yet there are still no concrete plans to tackle the problem. My own mother is currently undergoing cancer treatment, so I''ve seen first-hand the extra stress that that causes for people who are already worried about their health. I welcome the Government''s commitment in the supplementary budget to boost funding for the NHS, and I also hope that this budget passes to allow that support to happen. First Minister, do you agree that accessing healthcare should begin at the hospital entrance and not with a queue for a parking space? And what discussions is the Welsh Government having with Betsi Cadwaladr to ensure that this long-running problem is finally treated as a priority?', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Carrie Harper', '', '278', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=657&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:08.241740', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767466', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('970309428a96b4f62972', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '''Planning Policy Wales''', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', '', '', '', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', '', NULL, 60.5, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'Planning Policy Wales; planning policy', 0, '2026-08-04T14:03:05.156856', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768140', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97520a327c8825f75c5d', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'As my colleague Huw Thomas said, the Labour Members will be voting against the supplementary budget today. I want to be clear that I take absolutely no pleasure in this situation. This has always been and will always be about getting more funding for children and young people with ALN in Wales.

 I respectfully remind all the Plaid Cymru backbenchers who have made videos and statements over the weekend attacking Labour for our stance that there was not one single penny for additional learning needs in the supplementary budget until we in the Labour group started pushing for it. Not a single penny. As a result of the discussions this week, the Plaid Cymru minority Government has offered just £40 million for ALN this year, just 12 per cent of the consequential received as a result of the SEND announcement in England. Our view is that that is not enough.

 Yes, we need to invest in the transformation of ALN. That was one of the main findings of the ALN legislative review I commissioned and was something I was working on before the election. But we cannot do that without acknowledging and addressing the massive pressures that are in the system now, today. It is disingenuous of the Trefnydd, the First Minister and other Plaid Cymru Members to say that this was more than the money we put on the table, because the ALN consequentials were only announced in March, after the final budget was passed. So, it could not be allocated without a supplementary budget. Notwithstanding that, I''ve already told the Chamber that I asked for £100 million to be earmarked for ALN. That was the advice received from officials, the amount that we could spend in year.

 It''s not just Welsh Labour who don''t think £40 million is enough; every local authority of every political colour has called for more funding for ALN. And now we''ve heard from our trade union partners. The National Education Union has said they welcome the additional funding, but, based on their evidence from members, this doesn''t go far enough and more money needs to be spent. As I highlighted earlier, the National Association of Head Teachers and the Association of School and College Leaders have taken the unprecedented step of declaring a trade dispute with Welsh Government, citing ALN investment as one of the reasons. They are well aware of the latest offer from the Welsh Government. It is shocking that so early in this Senedd term the Government are in dispute with school leaders in Wales.

 Now, I recognise that Plaid Cymru won the election and are the biggest party, but you are still a minority party, and the way you have conducted some of the negotiations with my party does not bode well for the rest of this Senedd term. There have been some constructive discussions, but there have also been ultimata and negotiations conducted through the media and social media. I really wanted to get to a position where we could support your budget. Just this afternoon, we have asked the Government to withdraw the budget so we can continue negotiations and enable the Government to address the concerns of the teaching unions. If this budget does not pass today, it will be because of your intransigence.

 The finance Minister—[ Interruption .] The finance Minister has told the Chamber today that even if the budget doesn''t pass, you will still be able to spend the money on your priorities, but that you won''t spend money on ALN. Now, that will be your choice and, if I can say so, it will be an act of supreme spite.

 I have heard the heckles all afternoon from this Government that we are voting with Reform. That is beneath you on an issue of this importance, and it''s a sign that you cannot win the argument. So, I want to be clear: we are not voting with Reform, we are not voting with the Welsh Conservatives; we are voting with children and young people with additional learning needs, and we are voting for the school staff who support them, in the belief that those children and those school staff deserve more from this Plaid Cymru Government.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Lynne Neagle', '', '174', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=25074&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'final budget; supplementary budget', 0, '2026-08-04T14:03:10.706456', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767900', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97a65ac953be1259ba3e', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Yes, you''ve got to give me time.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elin Jones', '', '162', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=26310&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:10.844239', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#768000', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9826ecbc74fe619a9373', 'plenary_transcript', 'Plenary', '10. Voting Time', 'Item 8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill: For: 86, Against: 7, Abstain: 0

 Motion has been agreed

 Click to see vote results', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', '', '', '', '', '', 'Plenary', '10. Voting Time', '16085', '', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'Legislative Consent Motion', 0, '2026-08-04T14:03:10.867070', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767986', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('98a733d59a1149358dbb', 'consultation', 'Welsh Government — Consultation (notification)', 'Consultation: New tax rules for second homes and self-catering accommodation', 'Consultation: New tax rules for second homes and self-catering accommodation
The Welsh Government has launched a 12-week consultation on reducing the 182-day actual-letting threshold that self-catering properties must meet to be liable for non-domestic rates rather than council tax. The current test requires a property to be available to let for 252 days and actually let for 182 days.

 Five possible new exemptions are proposed: properties that form part of a wider business; large multi-unit properties; properties subject to planning restrictions; properties within the curtilage of the owner''s own residence; and properties on the owner''s farm.

 Read more: https://www.gov.wales/new-tax-rules-second-homes', 'https://www.gov.wales/new-tax-rules-second-homes', '2026-07-30', '', '', '', '', '', 'Welsh Government', '', '', '', NULL, 154.0, 'Critical', 'immediate', 'taxation_of_property; second_homes_and_short_term_lets', 'Planning & place; Tax & finance', '', 'Consultation open', '182 days; 252 days; consultation; council tax; non-domestic rates; second homes; self-catering', 0, '2026-08-04T14:04:54.647692', 'mailbox:senedd-monitor@nrla.org.uk:FIXTURE-003', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('99c93caa19a018369912', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: Legislation', 'Diolch, Lywydd, especially for that kind and polite reminder of bringing announcements like this first to the Senedd.

 First Minister, there are many aspects to welcome, I believe, in this statement, but I would appreciate clarity on a number of points. It was of course one of the Government''s key commitments to put rural-proofing on a statutory footing, and I look forward to scrutinising that legislation. I''ll be particularly interested to understand what outcomes it''ll drive for rural communities, because the test, of course, is not the drafting and the passage of the Bill, but what changes for rural communities. Likewise, on the fair rent Bill, I''m proud of how the last Welsh Labour Government strengthened protections for tenants, and my colleagues and I look forward to scrutinising the Government''s proposals in this area.

 I''d particularly like to welcome the Government''s announcement of a new law creating a community right to buy. This is a long-standing priority for many communities across Wales, and is particularly championed by the Co-operative Party. It empowers local people to bring valuable community spaces back into community ownership, and I know that work on this started under the last Welsh Labour Government. Of course, in England there is already a community right to buy, introduced by the UK Labour Government, and I''m a huge advocate of giving communities more power in decision making over their own areas. It''s exactly what the community right to buy helps to achieve—places like The Raven Inn in Llanarmon-yn-Iâl; I believe it''s frequented by Darren Millar many times. That shows just how powerful a community right-to-buy scheme can be in empowering and uniting a community. I think it''s an important tool in helping community groups to buy places like pubs, but also like schools, shops, open spaces and other places in towns and villages, and indeed in our cities. It protects places that make our communities special, that matter to people, and gives people more of a say in designing their own high streets.

 Now, the UK Labour Government''s backed this up with a fund to help communities to buy assets. So, what additional practical support will this Government put in place to ensure that communities can actually make use of the new law? I''d particularly suggest that the community facilities programme could be a useful vehicle for providing financial support and indeed advice to communities that need it.

 The First Minister won''t be surprised to hear me raise legislation for a school staff negotiating body in the Siambr. I''m disappointed to see that it''s not included in the statement today. We committed, when we were in Government, to a school support staff negotiating body, and much of the preparatory work is done. It''s ready to go, in fact. And, of course, when the Senedd recently voted on this matter, there was cross-party support for it. We were always clear, though, in Government that a new negotiating body would have addressing year-round pay as its first priority, because across Wales, 27,000 school support staff—the teaching assistants, the kitchen staff, caretakers and many others that schools rely on—are only being paid during term time. And, of course, we''re mere days away from the school summer holidays, a time at which, at least symbolically, these vital staff members are without pay. And it is about fair pay, it''s about job security, it''s about social justice, it''s about stability for children, and it''s also about equality, because 90 per cent of school support staff are women. For thousands of families across Wales, year-round pay would be a huge step forward, and I would urge the Government to commit to taking this forward as soon as possible.

 Now, another Bill I''d hoped to see in today''s statement was a taxi and private hire vehicles Bill, which, as many Members will know, was developed as a White Paper under the Welsh Labour Government. Such a Bill would legislate to regulate the taxi and private hire vehicle sector, including addressing the problem of cross-bordering, which is particularly prevalent in Cardiff and Newport. Now, since the White Paper, the need for this legislation has only increased. There''s no doubt about it. We now live in an age of rapidly evolving technology, particularly with regard to automation, that will fundamentally change how people across Wales work, how they travel and therefore how they use taxis and private hire vehicles. This legislation, I believe, will only become more relevant and necessary as the pace of change continues to increase, and I''d urge the Government to give this matter close consideration. Diolch.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Ken Skates', '', '267', '', '', 'Plenary', '4. Statement by the First Minister: Legislation', '16085', 'http://www.senedd.tv/en/16085?startPos=9312&l=en', NULL, 159.5, 'Critical', 'immediate', 'rent_controls_and_affordability; social_housing', 'Housing system; Private rented sector', 'First Minister / Cabinet; Opposition housing leads', 'Legislative commitment', 'White Paper; community right to buy; fair rent; right to buy', 0, '2026-08-04T14:03:09.043340', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767755', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9a34dbe1708ce66c7f86', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Diolch, Weinidog, for your commitment to championing a community-centred planning system and strengthening the voice of local people. Cymru is emerging as a significant location for data-centre development, with two designated UK Government AI growth zones. However, they have no dedicated use class and no mention in ''Planning Policy Wales'', even though their scale and energy and water demands raise important questions for our environment and our planning system beyond their immediate locality. As you know, in my own constituency of Caerdydd Ffynnon Taf, a data centre is proposed in Llanrumney, replacing the Cardiff east park and ride, which serves the University Hospital of Wales, and this has given rise to a controversy beyond the immediate locality. The proposed 150 MW facility, only a short distance from primary schools and local homes, will rely on fossil-fuelled gas turbines as well as polluting standby diesel generators. Will the Minister, therefore, set out what plans the Government has to review the planning requirements for data centres, and in particular look into the Cardiff east park-and-ride application, so that communities like Llanrumney don''t end up paying the social and environmental price while the profit goes elsewhere? Diolch.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Nick Carter', '', '12173', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4999&l=en', NULL, 60.5, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'Planning Policy Wales; planning policy; planning system', 0, '2026-08-04T14:03:05.173440', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768167', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9a90dd8d855e8871d683', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: Legislation', 'Whilst I''m grateful to the Government for the advance notice of these legislative priorities issued via the media this morning, surely Government announcements, especially when they relate to Bills to be introduced in this place, should be first made in this place, out of respect for all Members of this Parliament. I would encourage the Government to reflect on that and treat this place with the respect that it deserves.

 The statement refers to this programme as a far-reaching and ambitious programme that reflects the values of the Government. That may be so if the bar is set low. It doesn''t squarely reflect the priorities of the people of Wales. On the cost of living, making rents fairer is a noble aim, but the root cause of unaffordable rents is the housing shortage. The Government should be tackling the root cause of this by overhauling the planning system, giving house builders more certainty and skilling up our young people for a lifetime of work in construction. We should also be giving councils more powers to say ''no'' to houses in multiple occupation.

 The new development agency is an admission that this Government does not possess the expertise to directly deal with business and industry. For a moment there during the First Minister''s speech, I thought that the Minister for enterprise was coming to sit next to me to tell me so. He got a little lost in the Chamber, and I think that''s an omen for how lost the Government is on its policy with the economy. But businesses want to deal with decision makers, not agencies acting as a sales force. They want decisions on planning, on land assembly, on grant funding and business rate incentives. No quango can offer that. Plaid have finally got power and they''re handing it over to yet another quango. Far from creating more quangos, we should be consolidating them and bringing their functions in-house and saving on the extortionate management costs.

 On rural-proofing, as was the case with the sustainable farming scheme, the devil will be in the detail. It sounds like another environmental sustainability scheme, but what rural communities need is the Government off their backs when it comes to food production, and acting fairly when it comes to transport, health and education. Food security and increasing food exports is a large part of rural-proofing. Where is the legislation to safeguard those sectors?

 On tribunals, not one voter in Wales told me they wanted tribunal reform, but I do understand the importance of the tribunal system. But the language used to justify it is all about making the case for further devolution of justice and taking us on Plaid''s journey to independence.

 On water reform, my group tabled a motion to clean up our waters, our seas, our rivers, which Plaid shamefully voted against. Today''s announcement is a welcome u-turn, and I''m pleased that Plaid are now following Reform''s lead on this topic. And there could be room for consensus on this—hopefully so; you talked about consensus, First Minister. 

 Tackling child poverty—sadly, three decades of devolution has done little to eradicate poverty in Wales, and giving free childcare to all families, even those where the parents are millionaires, isn''t going to make the impact the Government expects. I understand the aim is for parents to be able to go out and work, but where are the jobs? Where is the plan for an economic boom in Wales?

 This Government appears to have chosen topics where it thinks there is consensus, and I understand why a minority Government would do that. But another approach would be to unite this Chamber with a more ambitious vision for Wales—a vision that sees Wales lead in certain sectors, such as nuclear energy and logistics, a vision that sees farmers produce even more of our high-quality food to export, to enable a radical step change in house building, and to significantly tighten up the performance management of the health boards, the health chiefs and the education sector.

 Wales has so much potential, but this programme does little to unleash it. We''ve seen these kinds of Bills and measures before. They have made little difference to the daily lives of the people of Wales. People voted for change, but they''ve ended up with continuity. Where Reform can see merit in legislation, we will support, we will offer our own ideas, but this is a missed opportunity to take Wales''s story to another level, and I can''t help but feel that the people of Wales will be underwhelmed when they see this programme as a whole.

 Now, I know much can be achieved without laws and with the normal levers of Government, but we have waited 30 years for this moment. There are just under four years left of this term, and Reform will do all it can to increase the level of ambition in this Parliament. Diolch.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Dan Thomas', '', '12147', '', '', 'Plenary', '4. Statement by the First Minister: Legislation', '16085', 'http://www.senedd.tv/en/16085?startPos=8823&l=en', NULL, 214.5, 'Critical', 'immediate', 'rent_controls_and_affordability; hmos_and_standards; housing_supply; planning_system; fiscal_and_legislative_context', 'Context; Planning & place; Private rented sector', 'First Minister / Cabinet; Opposition housing leads', '', 'house building; houses in multiple occupation; legislative priorities; multiple occupation; planning system; unaffordable rents', 0, '2026-08-04T14:03:08.983663', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767757', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9af045fbfbe0b8740e80', 'oral_question', 'Oral Question', 'Oral Question - OQ64420', 'What action is the Welsh Government taking to meet its social housing targets?', 'https://record.senedd.wales/OralQuestion/64420', '2026-07-08', 'Laura Anne Jones', '', '4562', '', 'Sir Fynwy Torfaen', 'Senedd (tabled business)', 'Tabled on 08/07/2026', '', '', NULL, 40.0, 'Low', 'dashboard', 'housing_supply; social_housing', 'Housing system; Planning & place', '', '', 'housing targets; social housing', 0, '2026-08-04T14:03:42.308411', 'record_search:type=oral_question:query=housing', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9b467eeb251857166257', 'plenary_transcript', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', 'Minister, the focus in this Chamber thus far has been on the cost of childcare plans, rather than on recognising childcare as a critical lever for reducing both poverty and inequality. Childcare is a complicated issue—just ask any parent attempting to fill out an eligibility form—but it''s essential economic and social infrastructure. And this is where we, across the political spectrum, must scrutinise your work. This policy will reduce child poverty and support women who''ve been forced out of the workplace by the motherhood penalty, which impacts everything from your pay packet to your pension. We saw on the doorstep how many people cared about this issue, which is why they voted for Plaid Cymru in their droves.

 The UK Labour Government took their eye off the ball, which is why we''ve ended up with the most expensive childcare, here in Wales, across the UK, and why parents have said to me that they''re moving out of Wales simply to make ends meet. Twenty-seven million pounds was reallocated out of the childcare budget in the last term, along with £140 million in Barnett consequentials that were lost due to the expansion of childcare in England. They haven''t been spent on childcare. Credit has to be given to Jane Dodds, who secured £30 million for Flying Start expansion. That helped support the roll-out of Flying Start in Merthyr. But I wish to ask why you, Minister, have made childcare a key priority for this Plaid Cymru Government, and, specifically, given that money that has been stripped from the childcare budget in the last term, what concrete milestones you have, particularly in the next six months, to ensure that we''re not just planning reform, but actively reversing the damage done to Welsh families.', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Sarah Rees', '', '5196', '', '', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', '16084', 'http://www.senedd.tv/en/16084?startPos=153&l=en', NULL, 77.0, 'Medium', 'digest', 'planning_system', 'Planning & place', 'First Minister / Cabinet; Opposition housing leads', '', 'planning reform', 0, '2026-08-04T14:03:15.452427', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#766806', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c2fcc66aaf420bc405f', 'consultation', 'Senedd — committee consultation', 'Priorities for the Local Government, Housing and Planning Committee', 'Priorities for the Local Government, Housing and Planning Committee

This is an open Senedd consultation. Responding puts NRLA''s position formally on the record.

Priorities for the Local Government, Housing and Planning Committee, start date: Fri, 17 Jul 2026 00:00:00 GMT, end date: Mon, 14 Sep 2026 23:59:00 GMT

Priorities for the Local Government, Housing and Planning Committee Priorities for the Local Government, Housing and Planning Committee View the background to this consultation View all current consultations Purpose of the consultation The L ocal Government, Housing and Planning Committee has been set up by the Senedd to look at policy and legislation, and to hold the Welsh Government to account on issues relevant to its remit. To help inform its planning, the Committee is seeking views from people and organisations on the top three issues they believe it should prioritise in the Seventh Senedd. To submit your views, please complete the online form . The closing date for sharing your views is 14 September 2026 . Providing Written Evidence The Senedd has two official languages, Welsh and English. In line with the Senedd’s Official Languages Scheme , the Committee welcomes contributions in both or either of our official languages, and we ask organisations that are subject to Welsh Language standards or schemes to respond in line with their own obligations. Please inform the Committee when submitting responses if you intend to provide a translation at a later date. Please see guidance for those providing evidence for committees . Disclosure of information Please ensure that you have considered the Senedd’s policy on disclosure of information before submitting information to the Committee. Contact details Should you wish to speak to someone regarding this consultation, please use the below contact details: Local Government, Housing and Planning Committee Welsh Parliament Cardiff Bay Cardiff CF99 1SN Email: SeneddHousing@senedd.wales Telephone: 0300 200 6565 Topics Helpful Links Find a Member of the Senedd chevron_right Sign up to updates from Senedd committees chevron_right Senedd Now chevron_right Glossary chevron_right Related No results were found

Closing date: 14 September 2026.', 'https://business.senedd.wales/mgConsultationDisplay.aspx?ID=626', '2026-07-17', '', '', '', '', '', 'Senedd committee', '', '', '', '2026-09-14', 224.0, 'Critical', 'immediate', 'committee_scrutiny', 'Housing system', 'NRLA named', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; closing date; consultation; consultations; seeking views; written evidence', 1, '2026-08-04T14:02:35.091543', 'https://business.senedd.wales/mgRss.aspx?f=76', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d242ac49de82d581434', 'other', 'Statement of Opinion', 'Statement of Opinion - OPIN-2026-0528', 'This Senedd: 1. Notes the efforts of successive governments to tackle fuel poverty and improve household energy efficiency, ...', 'https://record.senedd.wales/StatementOfOpinion/528', '2026-06-16', 'Vikki Howells', '', '5107', '', 'Pontypridd Cynon Merthyr', 'Senedd (tabled business)', 'Tabled on 16/06/2026', '', '', NULL, 35.0, 'Low', 'dashboard', 'energy_efficiency', 'Property & energy', '', '', 'fuel poverty', 0, '2026-08-04T14:04:11.001818', 'record_search:type=other:query=energy efficiency', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e601c965f9e44f9b5a7', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'Can you confirm that you understand that the money raised from the visitor levy is ring-fenced for visitor purposes, not to pay debt or anything else?', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Huw Thomas', '', '12156', '', '', 'Plenary', '7. Reform UK Debate: The tourism sector', '16084', 'http://www.senedd.tv/en/16084?startPos=13207&l=en', NULL, 38.5, 'Low', 'dashboard', 'taxation_of_property', 'Tax & finance', '', '', 'visitor levy', 0, '2026-08-04T14:03:16.895860', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#767093', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9ff913f4c22ca738aabb', 'legislation', 'Welsh Statutory Instruments 2025', 'The Council Tax (Alteration of Lists and Appeals) (Amendment) (Wales) Regulations 2025', 'The Council Tax (Alteration of Lists and Appeals) (Amendment) (Wales) Regulations 2025', 'https://www.legislation.gov.uk/wsi/2025/1323/made/data.xml', '2026-02-02', '', '', '', '', '', 'legislation.gov.uk', '', '', '', NULL, 45.5, 'Low', 'dashboard', 'taxation_of_property', 'Tax & finance', '', '', 'council tax', 0, '2026-08-04T14:04:15.218802', 'https://www.legislation.gov.uk/wsi/2025/data.feed', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a10fad88d1d0001cfea6', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Welsh Labour''s red lines on the supplementary budget have been clear from the outset: a substantial contribution for additional learning needs in our schools, utilising some—not all, some—of the consequential made available by the UK Government spend in this area in England. Plaid Cymru''s initial proposals contained not one penny for ALN. This fact is made very clear by the concerns raised in the Finance Committee report. A petition on this issue attracted 11,000 signatures in two weeks. And in the end, seven days ago, Plaid finally put some money on the table.

 We are clear this is not enough, but this is not our view alone. As has been said before, Welsh councils are united on how the pressures from ALN in schools are real and urgent. Many of us will have received correspondence from school leaders, outlining the immediate difference extra real funding could make, and we are all aware of the concerns felt by teaching unions. Extraordinarily, overnight, the two teaching unions that represent school leaders, the NAHT and ASCL, have written jointly to Welsh Government to state that they are now in formal dispute with the Government over the issue of pay and ALN funding. These aren''t militant unions. They''re not affiliated with the Labour Party. In fact, one of them used to be led by the education Minister.

 So, how has it come to this, just 64 days into a new Plaid Cymru Government, where two large, well-respected unions are having to ask for the intervention of an independent conciliation body to mediate its dealing with Welsh Government? It''s unprecedented. It''s a failure of social partnership, and it says very clearly that the supplementary budget, as proposed, isn''t good enough. Not our assessment; the blunt assessment of teachers, school leaders and their representatives.

 I heard the Trefnydd''s response to Lynne Neagle earlier in the business statement. It sounded to me very much like the response of a Government that''s stopped listening. Let me spell it out. Forty million pounds in one year is a bad deal. Forty million pounds in the second year, when it''s been eroded by inflation and demand growth, is a bad deal. Forty million pounds in the third year, when £200 million of further recurring consequential become available from ALN spend in England, is a ridiculous deal. No financially literate party could sign up to it.

 Llywydd, this Senedd Labour group is returning to our party''s foundational mission, being the political representation of organised labour in the nation and being the voice of the most vulnerable in our society. You will understand, therefore, given the fundamental and formal concerns that unions have regarding these proposals, how we simply cannot support the supplementary budget as it currently stands. There are some on the Plaid benches that are avowed socialists. Here is an early test for you: will you blindly follow your party''s whip, or will you vote with our pupils and our teachers?

 And let''s also be clear, Llywydd—[ Interruption .] Let''s also be clear—', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Thomas', '', '12156', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=24002&l=en', NULL, 71.5, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; supplementary budget', 0, '2026-08-04T14:03:10.584289', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767877', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a1ef9dff70304937e6ad', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'No, I was looking for it.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elin Jones', '', '162', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=23409&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:10.522792', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767983', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a3a63ab3c2993396d9df', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you. One area that I could say that definitely needs updating is the way that the Welsh Government''s energy policy is in planning policy, especially regarding ''Future Wales: the national plan 2040''. We all know that is outdated in regard to industrial-scale wind turbines and pylons across a vast part of rural mid and west Wales. We all know about the 220m turbines that are going to be erected if Bute Energy have their way. That would absolutely decimate my communities. But, in ''Future Wales'', it doesn''t actually take into consideration the current size of those turbines that are currently being proposed. It also doesn''t take into consideration the low-frequency noise that they generate as well. So, I''m asking you, Minister: are you willing to put a moratorium on these large-scale industrial plans for rural mid and west Wales, because unless planning policy is updated, we are going to see something potentially approved that will have devastating long-term impacts on communities without having updated planning guidance to make an informed decision?', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'James Evans', '', '8585', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4863&l=en', NULL, 71.5, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister; Other committee chairs', '', 'Future Wales; planning guidance; planning policy', 0, '2026-08-04T14:03:05.162095', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768151', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4edb171563b5ae923a2', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much for that question and for an opportunity to explain some of what was contained within the written statement issued on Monday. You''re exactly right, we want that target of 20,000 to include vacant properties above shops on our high streets, and this will be part of the work of the town centre taskforce, of course, and how we accelerate the process to allow more vacant properties to come into our housing stock.

 I do emphasise that I think it''s important to be entirely transparent and, therefore, I have said that only homes that will remain as social homes for communities and families will be counted as part of that 20,000 target. Now, what exactly the percentage will be between new builds and acquisitions in terms of vacant properties and so on, I can''t give you an exact figure on that. But, also in that statement made on Monday, I have spoken of community-led housing and I would like to include housing that''s created through community groups—through the community right to buy, for example—and that we also include those within the target because they do provide a solution that is in keeping with those communities in rural areas and where the Welsh language prospers.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4546&l=en', NULL, 77.0, 'Medium', 'digest', 'housing_supply; social_housing', 'Housing system; Planning & place', 'Housing minister', '', 'community right to buy; right to buy; social homes', 0, '2026-08-04T14:03:05.129226', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768122', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5c74391fe628d4a12a2', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'Thank you for the question from the Member. As the Member said, in the supplementary budget yesterday, as far as health is concerned, we had a focus on outcomes, on improving people''s health and well-being by introducing more funding into tackling the waiting lists, and it was extremely disappointing, to say the least, to see people who have said that they wanted to support such a policy vote against it. We want to improve people''s outcomes and make sure that the impact on patients is better. So, we have made sure that NHS Wales Performance and Improvement are now involved. They have agreed an intervention approach in the Aneurin Bevan University Health Board to support them. Their improvement plan focuses on supporting frail and older people in the community—exactly answering the points that the Member raised—increasing the front-door capacity for people with complex needs and ensuring timely discharge. We have also allocated an additional £3 million this year to enable the delivery of the improvement plan.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Mabon ap Gwynfor', '', '269', '', '', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', '16086', 'http://www.senedd.tv/en/16086?startPos=194&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:04.684752', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768029', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5e0f6c8e2a2821ac2c5', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'As someone who was a county councillor until recently, I can attest to how important it is to pass this supplementary budget today in order to address the challenges facing local government. Labour has made much over the last few weeks of the need to see urgent investment in ALN services, and everyone recognises that. It is therefore strange to hear today that they intend to vote against the budget, despite the fact that there is more money for ALN services in this budget than they themselves had originally called for. I''m sure that the families, teachers and pupils, who are calling for the same investment, will find that strange and frustrating too.

 Beyond the funding for ALN services, the supplementary budget also ensures additional investment for expanding free school meals and improving the condition of our schools. I am sure that everyone across the Chamber shares the same desire to see pupils with full stomachs learning in schools that are fit for purpose. But, by voting against the budget today, we are preventing that investment from reaching our schools as soon as possible, and it is the pupils and teachers who will miss out.

 Llywydd, it is not just the additional direct funding that is essential for the sustainability of our local authorities. The additional investment of £145 million in the health service takes pressure off care services. The £55 million for childcare creates local jobs and helps parents back into work in order to strengthen our local economy. And the £8 million for the bus travel scheme for young people improves connectivity and enables our young people to socialise and make use of local resources.

 In conclusion, Llywydd, the vote before us tonight asks a relatively simple question, really: do we want to see a sustainable health service? Do we want to give every child across Wales the best start? And do we want to support all pupils to realise their potential and all teachers to enjoy their work? We can only do that by passing the budget before us, and I encourage all Members to support it. Thank you.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elfed Williams', '', '12165', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=24654&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:10.658942', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767904', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a60cd69d5764819eed88', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Diolch, Lywydd. I''m pleased to speak in this debate today on behalf of the Finance Committee. We had the privilege of scrutinising the first supplementary budget on 9 July and our report makes 22 recommendations. Today, I will focus on some of our key recommendations. 

 As we''ve heard, the supplementary budget that the committee scrutinised included £246 million of unallocated resource funding, which the Cabinet Minister said reflects substantial in-year pressures, particularly within the NHS. We recognise that there is always some uncertainty at this stage of the financial year and that Governments need a degree of flexibility to respond to emerging pressures, but the level of unallocated funding is considerably higher than in recent supplementary budgets. The committee noted that the average over the last four years has been £62 million and it''s currently around four times higher than the average of the last four years. We want to better understand what pressures remain across Government and how those pressures differ from the normal challenges of managing a budget through the financial year.

 Turning to the management of NHS finances, this supplementary budget includes a £100 million allocation to tackle NHS waiting lists. The committee supports the Government''s ambition to move beyond short-term interventions and deliver sustained improvement in NHS performance. And we heard the Cabinet Minister wants to focus on longer term outcomes rather than short-term monthly performance measures. We heard that the NHS is currently facing financial pressures of more than £300 million this year and that discussions with health boards are ongoing before further funding decisions are taken. However, what we did not hear in sufficient detail is how the approach of this Government differs from previous approaches that have also relied on significant in-year NHS allocation. That is why we asked the Cabinet Minister to detail the accountability mechanisms and measures in place to ensure the £100 million for reductions in waiting lists is used effectively, and to explain the practical differences between the previous approaches to NHS funding and the new Government''s approach. We want to understand how these investments will drive sustainable improvement rather than short-term recovery measures.

 Moving on to the allocation of funding arising from the one-off special educational needs and disabilities consequential. Firstly, we recognise that the principle that Barnett consequentials do not have to be spent in the same way as funding allocated in England is an important principle. We also recognise the very real pressures facing additional learning needs services across Wales in the here and now. The Cabinet Minister told us that this one-off consequential has been absorbed into wider budget management. That inevitably raises questions about sustainability in other areas. We therefore ask her to explain how allocations enabled by this one-off consequential will be managed in future years, when that funding is no longer available. The Cabinet Minister told us the Government wants to work with local government and develop a more sustainable model for additional learning needs provision, recognising the significant pressure in the system. That is why we''re seeking greater clarity on both the scale of the challenge and the Government''s plan to manage these pressures.

 The committee noted the Government''s plans to expand funded childcare. The supplementary budget includes £55 million to accelerate the roll-out of funded childcare for two-year-olds and to support the wider expansion of the childcare offer. We asked the Cabinet Minister to confirm how many places the £55 million allocation will support, what outcomes are expected from the funding and how those outcomes will be monitored and reported.

 We will now turn to capital budgets. The Government has chosen to allocate virtually all available capital funding at this stage of the year. We understand the rationale and recognise the benefits of allocating capital funding early to facilitate delivery and support economic activity, however, that approach also leaves limited flexibility should circumstances change. We''re particularly concerned by reports that UK Government decisions associated with defence investment could have implications for Welsh capital budgets. We asked the Cabinet Minister to provide an assessment of the implications of the UK Government''s defence investment plan and any consequences for Welsh Government capital budgets.

 Too often, debate focuses solely on the amounts of money being spent; the Finance Committee understands that what matters most is what that money delivers. We look forward to the Cabinet Minister''s response and to continue our scrutiny of these issues as the financial year progresses. Diolch, Lywydd.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Sam Rowlands', '', '8734', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=23424&l=en', NULL, 60.5, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', '', 'Finance Committee; supplementary budget', 0, '2026-08-04T14:03:10.526566', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767956', NULL, NULL, NULL, NULL);
